INSERT INTO `questions` (`id`, `test_id`, `question_number`, `passage`, `prompt`, `options`, `correct_answer_index`, `module`, `image_url`, `question_type`, `correct_answer_text`, `section`) VALUES
(707, 17, 1, NULL, 'An artist made 12 pieces of pottery using 42 pounds of clay. The pottery included only bowls and vases. Each bowl used 2 pounds of clay and each vase used 4 pounds of clay. How many vases did the artist make?', '[\"3\",\"5\",\"7\",\"9\"]', 3, 1, NULL, 'mcq', NULL, 'reading'),
(708, 17, 2, NULL, 'One gallon of paint will cover 10 square feet of a surface. A room has a total wall area of \\(w\\) square feet. Which equation represents the total amount of paint \\(P\\), in gallons, needed to paint the walls of the room twice?', '[\"\\\\(P = 20w\\\\)\",\"\\\\(P = 10w\\\\)\",\"\\\\(P = \\\\frac{w}{5}\\\\)\",\"\\\\(P = \\\\frac{w}{10}\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'reading'),
(709, 17, 3, NULL, '[image] The table shows three values of \\(x\\) and their corresponding values of \\(y\\). There is a quadratic relationship between \\(x\\) and \\(y\\). An equation that represents this relationship can be written as \\(y = 24x^2 - bx - 128\\), where \\(b\\) is a constant. What is the value of \\(b\\)?', NULL, NULL, 1, 'https://i.postimg.cc/85pxm6jh/image.png', 'spr', '64', 'reading'),
(710, 17, 4, NULL, 'The equation \\(E(t) = 5(1.2)^t\\) gives the estimated number of employees at a certain business, where \\(t\\) is the number of years since the business opened. Which of the following is the best interpretation of the number 5 in this context?', '[\"The increase in the estimated number of employees each year\",\"The estimated number of employees when the business opened\",\"The percent increase in the estimated number of employees each year\",\"The number of years the business has been open\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(711, 17, 5, NULL, 'Line \\(t\\) in the \\(xy\\)-plane has a slope of \\(\\frac{1}{7}\\) and passes through the point \\((35, -8)\\). Which equation defines line \\(t\\)?', '[\"\\\\(y = -13x + \\\\frac{1}{7}\\\\)\",\"\\\\(y = \\\\frac{x}{7} - 13\\\\)\",\"\\\\(y = \\\\frac{x}{7} - 8\\\\)\",\"\\\\(y = 35x - 8\\\\)\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(712, 17, 6, NULL, 'The area of a rectangular region is increasing at a rate of 210 square feet per hour. Which of the following is closest to this rate in square meters per minute? (Use 1 meter = 3.28 feet.)', '[\"0.33\",\"1.07\",\"11.48\",\"19.52\"]', 0, 1, NULL, 'mcq', NULL, 'reading'),
(713, 17, 7, NULL, 'The scatterplot shows the relationship between \\(x\\) and \\(y\\) for the 9 data points in data set A. [image] A quadratic model for the data in data set A can be written as \\(y = 0.04x^2 - 0.07x + 6.59\\). The graph of this model is shown in the \\(xy\\)-plane. The data point at \\(x = 0\\) was found to be the result of a recording error and was removed from data set A to create data set B, consisting of the remaining 8 data points. A quadratic model for the data in data set B can be written as \\(y = ax^2 + bx + c\\), where \\(a\\), \\(b\\), and \\(c\\) are constants. If the quadratic models for data sets A and B are calculated in the same way, which of the following statements must be true? I. \\(a > 0.04\\) II. \\(c < 6.59\\)', '[\"I only\",\"II only\",\"I and II\",\"Neither I nor II\"]', 2, 1, 'https://i.postimg.cc/HL4fM2sm/image.png', 'mcq', NULL, 'reading'),
(714, 17, 8, NULL, '\\(f(x) = (2x - 7)(2x + 5)\\) What is the minimum value of the given function?', '[\"-36\",\"\\\\(-\\\\frac{5}{2}\\\\)\",\"\\\\(\\\\frac{1}{2}\\\\)\",\"2\"]', 0, 1, NULL, 'mcq', NULL, 'reading'),
(715, 17, 9, NULL, '\\(2x^2 + 18x + 2y^2 + 12y = \\frac{15}{2}\\) The given equation defines a circle in the \\(xy\\)-plane. What is the radius of the circle?', '[\"\\\\(\\\\frac{\\\\sqrt{30}}{2}\\\\)\",\"\\\\(\\\\sqrt{15}\\\\)\",\"\\\\(\\\\sqrt{33}\\\\)\",\"\\\\(\\\\frac{\\\\sqrt{498}}{2}\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'reading'),
(716, 17, 10, NULL, '[image] Note: Figure not drawn to scale. A right triangle has the dimensions shown, in centimeters (cm). What is the area of this triangle, in \\(\\text{cm}^2\\)?', NULL, NULL, 1, 'https://i.postimg.cc/fyLnD9N6/image.png', 'spr', '12', 'reading'),
(717, 17, 11, NULL, '[image] In the figure, line \\(AB\\) is parallel to line \\(CD\\), and line \\(AD\\) intersects line \\(BC\\) at point \\(E\\). If \\(y = 119\\) and \\(z = 113\\), what is the value of \\(x\\)?', '[\"52\",\"67\",\"128\",\"142\"]', 2, 1, 'https://i.postimg.cc/htVwFrmV/image.png', 'mcq', NULL, 'reading'),
(718, 17, 12, NULL, 'A researcher investigated two species of mites: a predator and its prey. At the start of a week, there was an equal number of the two species. At the end of the week, the number of prey had increased by 1900% of the number of prey at the start of the week, and the number of predators had increased by 240% of the number of predators at the start of the week. The number of predators at the end of the week was \\(p\\%\\) less than the number of prey at the end of the week. What is the value of \\(p\\)?', NULL, NULL, 1, NULL, 'spr', '83', 'reading'),
(719, 17, 13, NULL, 'Which expression is NOT a factor of \\(6,480x^4 - 1,280\\)?', '[\"\\\\(9x^2 + 4\\\\)\",\"\\\\(3x^2 - 2\\\\)\",\"\\\\(3x + 2\\\\)\",\"80\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(720, 17, 14, NULL, '\\(-4x + 24px = 72\\) In the given equation, \\(p\\) is a constant. The equation has no solution. What is the value of \\(p\\)?', '[\"0\",\"\\\\(\\\\frac{1}{6}\\\\)\",\"\\\\(\\\\frac{3}{4}\\\\)\",\"3\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(721, 17, 15, NULL, 'A zoologist observed the nests of wood ducks in an area. Each year, the zoologist recorded the number of eggs in each of the first 35 nests that were observed and created a frequency table for the data set. Which of the following frequency tables represents the data set with the smallest standard deviation?', '[\"https://i.postimg.cc/8cqy9JPn/image.png\",\"https://i.postimg.cc/502kCWRP/image.png\",\"https://i.postimg.cc/VLCZMRDp/image.png\",\"https://i.postimg.cc/cLG9cnzy/image.png\"]', 3, 1, NULL, 'mcq', NULL, 'reading'),
(722, 17, 16, NULL, '\\((x + 2)(x - 12) = 0\\) What is the positive solution to the given equation?', NULL, NULL, 1, NULL, 'spr', '12', 'reading'),
(723, 17, 17, NULL, 'The function \\(f\\) is a quadratic function. In the \\(xy\\)-plane, the graph of \\(y = f(x)\\) has a vertex at \\((1, 4)\\) and passes through the points \\((2, 28)\\) and \\((-1, 100)\\). What is the value of \\(f(-2) - f(0)\\)?', '[\"76\",\"124\",\"192\",\"220\"]', 2, 1, NULL, 'mcq', NULL, 'reading'),
(724, 17, 18, NULL, '\\(2x^2 + 14x + 2y^2 + 20y = \\frac{15}{2}\\) The given equation defines a circle in the \\(xy\\)-plane. What is the radius of the circle?', '[\"\\\\(\\\\frac{\\\\sqrt{30}}{2}\\\\)\",\"\\\\(\\\\sqrt{15}\\\\)\",\"\\\\(\\\\sqrt{41}\\\\)\",\"\\\\(\\\\frac{\\\\sqrt{626}}{2}\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'reading'),
(725, 17, 19, NULL, '\\(y = 6x^2 - 48x + 99\\) \\(y + 4 = 0\\) How many solutions are there to the given system of equations?', '[\"There is exactly 1 solution.\",\"There are exactly 2 solutions.\",\"There are exactly 3 solutions.\",\"There are no solutions.\"]', 3, 1, NULL, 'mcq', NULL, 'reading'),
(726, 17, 20, NULL, '[image] The triangle in the figure above has side lengths 3, 4, and \\(2x\\). Which of the following is NOT a possible value of \\(x\\)?', '[\"1\",\"2.5\",\"3\",\"5\"]', 3, 1, 'https://i.postimg.cc/5yvGxqGW/image.png', 'mcq', NULL, 'reading'),
(727, 17, 21, NULL, 'Line \\(p\\) in the \\(xy\\)-plane contains the points \\((6, 0)\\) and \\((6, 6)\\). Which equation defines line \\(p\\)?', '[\"\\\\(x = 0\\\\)\",\"\\\\(x = 6\\\\)\",\"\\\\(y = 0\\\\)\",\"\\\\(y = 6\\\\)\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(728, 17, 22, NULL, 'The function \\(f\\) is defined by \\(f(z) = 3z\\). Which of the following is equivalent to \\(f(z - 7)\\)?', '[\"\\\\(-3z\\\\)\",\"\\\\(3z - 7\\\\)\",\"\\\\(3z - 21\\\\)\",\"\\\\(-3z + 21\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'reading'),
(729, 17, 1, NULL, 'The expression \\(\\frac{kx - 17}{2x^2 - 11x + 15}\\) is equivalent to \\(\\frac{p}{x - 3} - \\frac{1}{2x - 5}\\), where \\(k\\) and \\(p\\) are constants. What is the value of \\(p\\)?', '[\"\\\\(-16\\\\)\",\"\\\\(\\\\frac{14}{5}\\\\)\",\"\\\\(4\\\\)\",\"\\\\(7\\\\)\"]', 2, 2, NULL, 'mcq', NULL, 'reading'),
(730, 17, 2, NULL, 'The measure of angle \\(F\\) is \\(\\frac{\\pi}{12}\\) radians. If the measure of angle \\(F\\) is \\(3n\\) degrees, where \\(n\\) is a constant, what is the value of \\(n\\)?', '[\"\\\\(3\\\\)\",\"\\\\(5\\\\)\",\"\\\\(12\\\\)\",\"\\\\(15\\\\)\"]', 3, 2, NULL, 'mcq', NULL, 'reading'),
(731, 17, 3, NULL, 'The function \\(g\\) is defined by \\(g(x) = -2x(x + 4)(x - k)^2 + r\\), where \\(k\\) and \\(r\\) are integer constants. In the \\(xy\\)-plane, the graph of \\(y = g(x)\\) passes through the point \\((8, 17)\\), and \\(g(0) = 17\\). What is the value of \\(r + k\\)?', '[\"\\\\(-8\\\\)\",\"\\\\(0\\\\)\",\"\\\\(17\\\\)\",\"\\\\(25\\\\)\"]', 3, 2, NULL, 'mcq', NULL, 'reading'),
(732, 17, 4, NULL, 'The function \\(f\\) is defined by \\(f(x) = 41(0.26)^x\\). For any positive integer \\(n\\), the value of \\(f(n)\\) is \\(p\\%\\) less than the value of \\(f(n - 1)\\). What is the value of \\(p\\)?', '[\"\\\\(74\\\\)\",\"\\\\(59\\\\)\",\"\\\\(41\\\\)\",\"\\\\(26\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'reading'),
(733, 17, 5, NULL, '[image] The shaded region shown represents the solutions to which inequality?', '[\"\\\\(y \\\\ge -2x + 4\\\\)\",\"\\\\(y > 4x - 2\\\\)\",\"\\\\(y \\\\le -2x + 4\\\\)\",\"\\\\(y \\\\le 4x - 2\\\\)\"]', 0, 2, 'https://i.postimg.cc/MZjgbqGr/image.png', 'mcq', NULL, 'reading'),
(734, 17, 6, NULL, '\\(f(x) = 21(1.20)^{\\frac{x}{3}}\\)\n\nFor the given function \\(f\\), the value of \\(f(x)\\) increases by \\(p\\%\\) for every increase of \\(x\\) by \\(6\\). What is the value of \\(p\\)?', NULL, NULL, 2, NULL, 'spr', '44', 'reading'),
(735, 17, 7, NULL, 'A company developed a plan to set the selling price of a product. The company determined that for a selling price of \\(\\$90.00\\), zero products would be sold. For each \\(\\$1.50\\) decrease in the selling price, the number of products sold would increase by one. For a revenue of exactly \\(\\$1,336.50\\), which of the following could be the number of products sold? (\\(\\text{revenue} = \\text{price} \\times \\text{number of products sold}\\))', '[\"\\\\(27\\\\)\",\"\\\\(30\\\\)\",\"\\\\(831\\\\)\",\"\\\\(1,350\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'reading'),
(736, 17, 8, NULL, '\\(y = 4x^2 - 24x + 38\\)\n\\(y + 3 = 0\\)\n\nHow many solutions are there to the given system of equations?', '[\"There is exactly 1 solution.\",\"There are exactly 2 solutions.\",\"There are exactly 3 solutions.\",\"There are no solutions.\"]', 3, 2, NULL, 'mcq', NULL, 'reading'),
(737, 17, 9, NULL, '\\(-7x^2 + bx - 63 = 0\\)\n\nIn the given equation, \\(b\\) is a positive integer. The equation has no real solution. What is the largest possible value of \\(b\\)?', NULL, NULL, 2, NULL, 'spr', '41', 'reading'),
(738, 17, 10, NULL, 'If \\(5 + \\frac{2(13 - x)}{7} = 3(13 - x) + 5\\), what is the value of \\(13 + x\\)?', NULL, NULL, 2, NULL, 'spr', '26', 'reading'),
(739, 17, 11, NULL, 'The area of a rectangle is \\(60\\) square inches. The length of the longest side of the rectangle is \\(15\\) inches. What is the length, in inches, of the shortest side of this rectangle?', '[\"\\\\(4\\\\)\",\"\\\\(15\\\\)\",\"\\\\(30\\\\)\",\"\\\\(45\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'reading'),
(740, 17, 12, NULL, 'For the linear function \\(g\\), \\(g(9) = 11\\) and \\(g(x + 1) - g(x) = 2\\). Which equation defines \\(g\\)?', '[\"\\\\(g(x) = 9x + 2\\\\)\",\"\\\\(g(x) = 9x + 11\\\\)\",\"\\\\(g(x) = 2x - 18\\\\)\",\"\\\\(g(x) = 2x - 7\\\\)\"]', 3, 2, NULL, 'mcq', NULL, 'reading'),
(741, 17, 13, NULL, '[image] For the linear function \\(f\\), the table shows three values of \\(x\\) and their corresponding values of \\(f(x)\\). Function \\(f\\) is defined by \\(f(x) = rx + s\\), where \\(r\\) and \\(s\\) are constants. What is the value of \\(rs\\)?', NULL, NULL, 2, 'https://i.postimg.cc/c1Y5thDR/image.png', 'spr', '507', 'reading'),
(742, 17, 14, NULL, '\\(57x^{18} + bx^9 + 34\\)\n\nThe given expression, where \\(b\\) is a constant, is equivalent to \\((3x^9 + q)(rx^9 + 2)\\), where \\(q\\) and \\(r\\) are constants. What is the value of \\(b\\)?', NULL, NULL, 2, NULL, 'spr', '36', 'reading'),
(743, 17, 15, NULL, '\\(g(x) = x^3 + ax^2 + bx + c\\)\n\nThe function \\(g\\) is defined by the given equation, where \\(a\\), \\(b\\), and \\(c\\) are integer constants. The zeros of the function are \\(-2\\), \\(-7\\), and \\(3\\). What is the value of \\(a\\)?', '[\"\\\\(-42\\\\)\",\"\\\\(-6\\\\)\",\"\\\\(6\\\\)\",\"\\\\(42\\\\)\"]', 2, 2, NULL, 'mcq', NULL, 'reading'),
(744, 17, 16, NULL, 'A circle in the \\(xy\\)-plane has its center at \\((-4, 4)\\) and has a radius of \\(6\\). An equation of this circle is \\(x^2 + y^2 + ax + by + c = 0\\), where \\(a\\), \\(b\\), and \\(c\\) are constants. What is the value of \\(c\\)?', NULL, NULL, 2, NULL, 'spr', '-4', 'reading'),
(745, 17, 17, NULL, 'A model estimates that the population of a state was \\(4\\) million in 1980 and increased by \\(0.041\\) million each year until 2007. According to the model, what was the estimated population of this state, in millions, \\(10\\) years after 1980?', NULL, NULL, 2, NULL, 'spr', '4.41', 'reading'),
(746, 17, 18, NULL, 'In triangle \\(RST\\), angle \\(T\\) is a right angle, point \\(L\\) lies on \\(\\overline{RS}\\), point \\(K\\) lies on \\(\\overline{ST}\\), and \\(\\overline{LK}\\) is parallel to \\(\\overline{RT}\\). If the length of \\(\\overline{RT}\\) is \\(63\\) units, the length of \\(\\overline{LK}\\) is \\(21\\) units, and the area of triangle \\(RST\\) is \\(252\\) square units, what is the length of \\(\\overline{KT}\\), in units?', NULL, NULL, 2, NULL, 'spr', '112/21', 'reading'),
(747, 17, 19, NULL, 'A car dealership has only sedans, SUVs, and minivans for sale. On Monday, \\(20\\%\\) of the vehicles for sale were sedans and \\(50\\%\\) were SUVs. If there were \\(62\\) sedans for sale at the dealership on Monday, how many minivans were for sale?', '[\"\\\\(93\\\\)\",\"\\\\(310\\\\)\",\"\\\\(9\\\\)\",\"\\\\(36\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'reading'),
(748, 17, 20, NULL, 'An exponential function \\(f\\) gives the estimated amount of an X-ray beam\'s initial intensity remaining after passing through a \\(w\\)-centimeter-thick window made of beryllium. The function estimates that after passing through a \\(1.8\\)-centimeter-thick window, the amount of the X-ray beam\'s initial intensity remaining is \\(0.65\\). Which equation could define \\(f\\)?', '[\"\\\\(f(w) = 0.65(0.79)^{w - 1.8}\\\\)\",\"\\\\(f(w) = 0.65(0.79)^{\\\\frac{w}{1.8}}\\\\)\",\"\\\\(f(w) = 0.65(1.8)^w\\\\)\",\"\\\\(f(w) = 1.8(0.65)^w\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'reading'),
(749, 17, 21, NULL, '[image] In the figure, \\(\\overline{BC}\\) is parallel to \\(\\overline{DE}\\). If the length of \\(\\overline{DE}\\) is \\(162\\) and the length of \\(\\overline{AE}\\) is \\(270\\), what is the value of \\(\\tan x^\\circ\\)?', '[\"\\\\(\\\\frac{270}{162}\\\\)\",\"\\\\(\\\\frac{216}{162}\\\\)\",\"\\\\(\\\\frac{162}{270}\\\\)\",\"\\\\(\\\\frac{162}{216}\\\\)\"]', 1, 2, 'https://i.postimg.cc/CxvvpQ1Y/image.png', 'mcq', NULL, 'reading'),
(750, 17, 22, NULL, 'The function \\(f\\) is defined by \\(f(x) = |x - 6x|\\). What value of \\(a\\) satisfies \\(f(1) - f(a) = -15\\)?', '[\"\\\\(-16\\\\)\",\"\\\\(3\\\\)\",\"\\\\(4\\\\)\",\"\\\\(75\\\\)\"]', 2, 2, NULL, 'mcq', NULL, 'reading'),
(751, 18, 1, 'The following text is from Mark Twain\'s 1876 novel The Adventures of Tom Sawyer. Tom, a child, has been told by his aunt to paint their house\'s fence.\n\nTom appeared on the sidewalk with a bucket of whitewash and a long-handled brush. He surveyed the fence, and all gladness left him and a deep melancholy settled down upon his spirit. Thirty yards of board fence nine feet high.', 'As used in the text, what does the word “surveyed” most nearly mean?', '[\"Praised\",\"Organized\",\"Examined\",\"Converted\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(752, 18, 2, 'The influence of William Shakespeare\'s writings is clear in a vast range of subsequent literary works and is similarly ______ in many works in other media, from fine art (such as Edward Alcock\'s painting Portia and Shylock) to popular music (such as the musician Elvis Costello\'s song “Miss Macbeth”).', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"subtle\",\"apparent\",\"unusual\",\"excessive\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(753, 18, 3, 'The Apollo Moon landings (1969–1972) brought charged particle detectors and temperature probes to the Moon and produced large amounts of data, much of which was stored on technologies that are now obsolete. A data-transfer project is working to ______ these data so that the information is available to researcher Seichi Nagihara, who is investigating temperature changes on the Moon.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"improve\",\"simplify\",\"amend\",\"salvage\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(754, 18, 4, 'The following text is adapted from the 1895 poem “Ojistoh” by Emily Pauline Johnson, a Kanienkahagen (Mohawk) writer also known as Tekahionwake.\n\nI am Ojistoh, I am she, the wife\n\nOf him whose name breathes bravery and life\n\nAnd courage to the tribe who calls him chief.\n\nI am Ojistoh, his white star, and he\n\nIs land, and lake, and sky—and soul to me.', 'As used in the text, what does the word “breathes” most nearly mean?', '[\"Imparts\",\"Renounces\",\"Assents\",\"Absorbs\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(755, 18, 5, 'Mastering \'ajami, a Syrian art of creating intricately painted wood panels, demands a skill set that____innate talent: crafting the panels requires not just the ability to draw but also an understanding of traditional techniques, materials, and design elements, necessitating expertise gained through dedicated guidance from experienced artisans.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"restrains\",\"replicates\",\"characterizes\",\"transcends\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(756, 18, 6, 'In factories, humans and robots often work together. A research team ran an experiment to find out how working with robots affects relationships between human coworkers. The experiment included teams working together to make electric motor parts. One type of team included only humans and the other type included both humans and robots. Participants were paid for their work and were asked about their willingness to share their earnings with their human teammates. Participants from teams with robots were more likely to share with each other than participants from teams with only humans were.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It states the results of the experiment discussed in the text.\",\"It indicates the question that the study discussed in the text was meant to answer.\",\"It explains an important part of the design of the experiment discussed in the text.\",\"It illustrates a problem that inspired the study discussed in the text.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(757, 18, 7, 'Steve Carter’s award-winning play Eden was produced in 1976 by the groundbreaking Negro Ensemble Company (NEC). NEC cofounder Douglas Turner Ward, who worked as an actor, director, and playwright, had met actor and producer Robert Hooks while they were performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun. Together, they envisioned a theater company that would nurture and showcase the work of Black theater professionals. Since NEC’s founding in 1967, its workshops and performances have given Black playwrights, including Carter, a forum for their compelling stories.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It illustrates the widespread influence of a play discussed earlier in the text.\",\"It provides additional information about a person mentioned in the text.\",\"It emphasizes the ongoing significance of the theater company discussed in the text.\",\"It explains the circumstances that led to the formation of the theater company discussed in the text.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(758, 18, 8, 'Despite potential independent confirmation, the apparent detection in 2020 of phosphine (PH₃)—a gas that on Earth almost exclusively derives from biological sources—in Venus’s cloud deck remains controversial, in part because Venus is thought to be uninhabitable. To evaluate such a finding’s plausibility, William Bains et al. modeled multiple abiotic PH₃ pathways, including geochemical, atmospheric, and photochemical reactions, but none adequately explain the observed levels of PH₃. If Venusian PH₃ does exist, it would indicate insufficiencies in the current consensus on Venus’s chemistry.', 'Which choice best describes the overall structure of the text?', '[\"It introduces an unexpected observation of a particular gas in Venus’s atmosphere, presents an effort to investigate possible mechanisms that could explain that observation, and then notes an implication of that investigation’s findings.\",\"It explains why the consensus view of a particular gas in Venus’s atmosphere has recently become controversial, expands on a scientific team’s reasons for questioning that consensus, and then suggests that future observations of Venus’s atmosphere will likely be needed to settle the controversy.\",\"It compares the levels of a particular gas on Venus and Earth, sketches the chemical processes that account for differences in these levels, and then addresses some of the practical challenges of studying the presence of this gas on Venus more closely.\",\"It outlines recent efforts to confirm the presence of a particular gas in Venus’s atmosphere, summarizes a research team’s evaluations of those efforts’ methodological shortcomings, and then explains why that team remains skeptical of the gas’s future detection.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(759, 18, 9, 'Given the immense scope of space, the search for extraterrestrial life is almost necessarily concentrated on the exoplanets deemed to have the most plausible chance of success—typically, atmosphere-bearing terrestrial planets orbiting within a certain range of their stars (termed the habitable zone). Claiming that Earth experienced a long transition from single-lid to plate tectonics that accelerated the emergence and evolution of complex organisms, researchers Robert J. Stern and Taras V. Gerya hold that consideration of tectonics, an often overlooked factor, could help further narrow the search for advanced extraterrestrial species.', 'Based on the text, what do Stern and Gerya most likely believe about the development of complex life on exoplanets?', '[\"It is more likely to occur on habitable zone planets with atmospheres and plate tectonics than on otherwise similar planets that lack plate tectonics.\",\"It is more likely to occur if habitable zone planets with atmospheres transition from single-lid to plate tectonics late in their history than if they transition early in their history.\",\"It is probably more dependent on the presence of plate tectonics than on orbital distance from a host star or the presence of an atmosphere.\",\"It is unlikely unless the transition from single-lid to plate tectonics occurs before the acquisition of a lasting atmosphere.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(760, 18, 10, 'Quality assessments of concrete typically focus almost exclusively on compressive strength as a measure of durability, overlooking other potentially relevant factors. Licsa Ptacek et al. therefore investigated the potential of gas permeability (vulnerability to incursion by gases), which is caused in part by excessive porosity, as a durability indicator. Their measurements and observations revealed that quality of conditions during the concrete curing phase negatively correlates with gas permeability and that high gas permeability values are associated with increased deterioration as concrete surfaces age.', 'Information in the text best supports which statement about Ptacek et al.’s findings?', '[\"They suggest that gas permeability testing presents a more reliable indication of concrete durability than compressive strength testing does.\",\"They bolster the claim that concrete’s susceptibility to damage decreases as its gas permeability increases.\",\"They call into question the idea that quality of curing conditions directly affects concrete gas permeability but is unrelated to compressive strength.\",\"They indicate that evaluation of gas permeability is an appropriate addition to concrete quality assessment procedures.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(761, 18, 11, 'The Wonderful Wizard of Oz is a 1900 novel by L. Frank Baum. In the novel, Dorothy, who is from Kansas, finds herself in an unfamiliar place called Oz. Kansas is presented as being less appealing than Oz, as is clear when ______.', 'Which quotation from The Wonderful Wizard of Oz most effectively illustrates the claim?', '[\"a character says to Dorothy, “I cannot understand why you should wish to leave this beautiful country and go back to the dry, gray place you call Kansas.”\",\"a character says to others, “But it will take more than imagination to carry Dorothy back to Kansas, and I’m sure I don’t know how it can be done.”\",\"the narrator states, “Dorothy did not feel nearly so bad as you might think a little girl would who had been suddenly whisked away from her own country and set down in the midst of a strange land.”\",\"the narrator states, “Before them was a great stretch of country having a floor as smooth and shining and white as the bottom of a big platter.”\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(762, 18, 12, '<table class=\"passage-table\" border=\"1\" style=\"border-collapse: collapse; width: 100%; margin-bottom: 15px;\"><tr><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Month</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average high (°F)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average low (°F)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average male wing centroid size (mm)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average female wing centroid size (mm)</th></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">October</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">67</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">44</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">1.98</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.29</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">July</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">87</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">62</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.02</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.31</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">June</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">80</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">56</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.01</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.31</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">May</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">73</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">50</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">1.98</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.27</td></tr></table>\n\nDrosophila (fruit flies) have generation times of 10–12 days, so seasonal changes in humidity and other environmental conditions can drive seasonal fluctuations in chromosome rearrangements in species such as D. persimilis and D. mediopunctata. Drosophila body size (for which wing centroid size serves as a proxy measure) correlates with life span. Banu Sebnem Önder and Cansu Fidan Aksoy measured the wing sizes of members of a D. melanogaster population in Yesilöz, Turkey, that were collected monthly between May and October over three years. Their research suggests that Drosophila collected in relatively cooler months should tend to have a shorter life span, as is illustrated by the finding that ______.', 'Which choice most effectively uses data from the table to complete the assertion?', '[\"the average female wing centroid size was smaller in May than in June.\",\"the average male wing centroid size was consistently smaller than the average female wing centroid size in all four months in the table.\",\"the average monthly low temperature was lower in May than in June.\",\"the average male wing centroid size was 1.98 mm in May but was 2.31 mm in July.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(763, 18, 13, 'Rafael Núñez and colleagues studied how members of the Yupno, an Indigenous group in Papua New Guinea, conceptualize time in both spoken language and gestures. The researchers recorded Yupno speakers explaining certain temporal words and phrases, such as jare, a past-oriented expression that translates to “day before yesterday,” and coded each speaker’s manual gestures. Previous research has found a tendency in many cultures to make temporal distinctions along imagined linear axes: for instance, Hebrew speakers often refer to the right/left axis to describe events in time. Some researchers believe this tendency is universal, but Núñez and colleagues claim this is not the case.', 'Which finding, if true, would most directly support Núñez and colleagues’ claim?', '[\"Yupno speakers typically use their left hand to make temporal gestures regardless of whether the gestures are past oriented or future oriented.\",\"Future-oriented gestures used by Yupno speakers do not, on average, point in the opposite linear direction of past-oriented gestures.\",\"Some Yupno grammatical structures used when talking about time are also used in Hebrew.\",\"Yupno speakers were observed making temporal gestures both indoors and outdoors, though with greater frequency when indoors.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(764, 18, 14, 'The Man–Made World: Or, Our Androcentric Culture is a 1911 nonfiction work by Charlotte Perkins Gilman. In the text, the author emphasizes the importance of cultivating individuals rather than comparing them: ______.', 'Which quotation from The Man–Made World: Or, Our Androcentric Culture most effectively illustrates the claim?', '[\"“That every child on earth shall have right conditions to make the best growth possible to it; that every citizen, from birth to death, shall have a chance to learn all he or she can, to develop every power that is in them.”\",\"“We do not sadly measure the cabbage–stalk by the corn–stalk, and praise the corn for getting ahead of the cabbage—nor incite the cabbage to imitate the corn. We nourish both, to its best growth—and are the richer.”\",\"“We have but to learn the real elements in humanity; its true powers and natural characteristics.”\",\"“We are now to consider the growth of the family in humanity.”\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(765, 18, 15, 'Zooarchaeologist Ophélie Lebrasseur and her team examined a fox skeleton discovered in 1991 at an archaeological site alongside artifacts of human habitation (like spear points) in central Argentina. Lebrasseur et al. determined that the fox was Dusicyon avus, an extinct species resembling a jackal, and radiocarbon dating placed the fox at the site at the same time as human inhabitants. (Indeed, the inhabitants may have deliberately buried the fox.) In addition, while wild foxes have a diet entirely made of meat, isotopic signatures of the skeleton’s teeth indicated that the fox\'s diet, like that of the humans, was partly composed of plant material. Lebrasseur et al. therefore concluded that ______.', 'Which choice most logically completes the text?', '[\"the humans who were alive at the same time as the fox most likely ate more meat than the fox did.\",\"the fox had a diet more similar to that of jackals than to that of wild foxes.\",\"the humans who were alive at the same time as the fox hunted using the spears whose points were also found at the site.\",\"the fox may have been a companion animal of the humans who inhabited the site at the same time.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(766, 18, 16, 'In the nineteenth century, Elizabeth Cady Stanton and Susan B. Anthony ______ for women’s right to vote in the United States.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"having campaigned\",\"campaigned\",\"campaigning\",\"to campaign\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(767, 18, 17, 'While conducting an interview for her book Latina Authors and Their Muses, editor Mayra Calvani asked Sarah Cortez, author of the memoir Walking Home, what ______ Cortez\'s response was Bury Me Deep by Megan Abbott.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"her favorite book was.\",\"was her favorite book?\",\"her favorite book was?\",\"was her favorite book!\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(768, 18, 18, 'Choreographers George Balanchine and Martha Graham both contributed sections to the dance piece Episodes, which premiered at New York’s City Center of Music and Drama in 1959. This cross-genre collaboration brought together the distinct features of Balanchine’s neoclassical ballet and Graham’s modern ______ the stylistic diversity and creative innovation within the dance world.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"dance, it showcased\",\"dance. Which showcased\",\"dance, showcasing\",\"dance. Showcasing\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(769, 18, 19, 'In the book A Theory of Harmony (1985), Swiss musicologist Ernst Levy argued that every chord has an opposite that can be substituted for it. For example, a pianist could replace the vi chord for the III chord while ______ chord is a given chord\'s opposite can be determined using a music visualization tool called the circle of fifths.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"improvising which\",\"improvising and which\",\"improvising. Which\",\"improvising, which\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(770, 18, 20, 'In her Silueta sculpture series, the Cuban American artist Ana ______ to access what she called an “omnipresent female force,” utilized a variety of natural materials to create outlines—or silhouettes—of her own body.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"Mendieta was hoping\",\"Mendieta hoped\",\"Mendieta had hoped\",\"Mendieta, hoping\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(771, 18, 21, 'As volcanologists like Tamsin Mather are apt to make clear, not all volcanoes are the same. Tendürek in Turkey, for example, is a shield volcano, a type of volcano named for its low profile, resembling a warrior\'s shield lying on the ground. Opala in Russia, ______ is a caldera, a large cauldron-like hollow that forms shortly after the emptying of a magma chamber in a volcanic eruption.', 'Which choice completes the text with the most logical transition?', '[\"in any case,\",\"in contrast,\",\"in conclusion,\",\"in fact,\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(772, 18, 22, 'The United Nations’ Trade and Development organization divides exports into five key categories: food items, agricultural materials, fuels, ores and raw metals, and manufactured goods (i.e., most nonfood goods made by machinery or by hand). In 2022, the majority (62 percent) of Belgium\'s exports were manufactured goods. ______ vaccines, medicines, and cars were its top exports.', 'Which choice completes the text with the most logical transition?', '[\"In a broader sense,\",\"Within this category,\",\"In the future,\",\"Despite this majority,\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(773, 18, 23, 'A research team led by Gal Badihi has discovered that chimpanzees communicate through exchanges of gestures occurring at a pace similar to that of human conversations. ______ chimpanzee gesture exchanges have short pauses of about 120 milliseconds between communications, comparable to the 200-millisecond average pause between turns in human speech.', 'Which choice completes the text with the most logical transition?', '[\"Specifically,\",\"As a result,\",\"By contrast,\",\"Nevertheless,\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(774, 18, 24, 'While researching a topic, a student has taken the following notes:\n\nThe Great Salt Lake in Utah is one of the world\'s saltiest bodies of water.\n\nThe northern portion of the lake has a higher concentration of salt than the southern portion.\n\nAquatic insects called Ephydra cinerea live in the southern portion.\n\nBacteria called Nodularia live in the southern portion.', 'The student wants to emphasize a difference between Ephydra cinerea and Nodularia. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"Ephydra cinerea and Nodularia are different types of organisms: Ephydra cinerea are aquatic insects, whereas Nodularia are bacteria.\",\"The northern portion of the Great Salt Lake has a higher concentration of salt than does the southern portion.\",\"Ephydra cinerea and Nodularia both live in the Great Salt Lake\'s southern portion.\",\"Ephydra cinerea are aquatic insects that live in the southern portion of the Great Salt Lake.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(775, 18, 25, 'While researching a topic, a student has taken the following notes:\n\nExtravehicular activities (EVAs) are activities performed outside a spacecraft by astronauts in outer space.\n\nEVAs are also known as spacewalks.\n\nRichard Mastracchio is a former US astronaut who has performed 9 spacewalks.\n\nThe total time of Mastracchio\'s spacewalks was 53 hours and 4 minutes.\n\nGarrett Reisman is a former US astronaut who has performed 3 spacewalks.\n\nThe total time of Reisman\'s spacewalks was 21 hours and 21 minutes.', 'The student wants to emphasize a similarity between the astronauts Mastracchio and Reisman. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"Reisman has spent less time performing spacewalks than Mastracchio has.\",\"EVAs, also known as spacewalks, are activities done by astronauts outside a spacecraft.\",\"Mastracchio and Reisman have each performed multiple spacewalks.\",\"Mastracchio has performed spacewalks, but Reisman has performed EVAs.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(776, 18, 26, 'While researching a topic, a student has taken the following notes:\n\nThe Tijuana Slough National Wildlife Refuge (NWR) is a protected natural area in California.\n\nIt encompasses 1,023 acres.\n\nThe Tijuana Slough NWR was established to safeguard the habitat of the light-footed clapper rail, an endangered species.\n\nThe Tijuana Slough NWR is managed by the US Fish & Wildlife Service.\n\nThe US Fish & Wildlife Service limits human activities in the area.', 'The student wants to emphasize the role the US Fish & Wildlife Service plays in safeguarding the habitat of the light-footed clapper rail. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"By limiting human activities in the Tijuana Slough NWR, the US Fish & Wildlife Service safeguards the habitat of the light-footed clapper rail.\",\"Human activities are limited in the Tijuana Slough NWR, a protected natural area in California.\",\"Home to the light-footed clapper rail, the Tijuana Slough NWR is located in California, where it encompasses 1,023 acres.\",\"The 1,023-acre Tijuana Slough NWR was established to safeguard the habitat of the light-footed clapper rail, an endangered species.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(777, 18, 27, 'While researching a topic, a student has taken the following notes:\n\nThe cuneiform script is the earliest known set of symbols used for writing.\n\nSumerian was one of the first languages to be written using the cuneiform script.\n\nSumerian was a language in ancient Mesopotamia (present-day Iraq).\n\nClay tablets with Sumerian writing have been found there.\n\nSome of these tablets are almost 5,000 years old.', 'The student wants to identify a language that was written using the cuneiform script. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"Examples of Mesopotamian writing that are nearly 5,000 years old have been found.\",\"A language in ancient Mesopotamia used the cuneiform script for writing.\",\"Clay tablets with cuneiform script have been found in present-day Iraq.\",\"Sumerian, an ancient Mesopotamian language, was written using the cuneiform script.\"]', -1, 1, NULL, 'mcq', NULL, 'reading'),
(778, 18, 1, 'Zygomorphic (bilaterally symmetric) flowers remain open and functional on average 1.1 days longer than actinomorphic (radially symmetric) flowers do. Ruby E. Stephens and colleagues claim that this extended period could be ______ the relatively small pool of potential pollinators available to zygomorphic flowers and the greater chance at successful pollination that remaining open affords them.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"analogous to\",\"magnified by\",\"converted by\",\"attributed to\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(779, 18, 2, 'The following text is from Charles Dickens’s 1861 novel Great Expectations. The narrator is taking a walk near his home on a damp morning.\n\nOn every rail and gate, wet lay clammy, and the marsh mist was so thick, that the wooden finger on the post directing people to our village—a direction which they never accepted, for they never came there—was invisible to me until I was quite close under it.', 'As used in the text, what does the word “accepted” most nearly mean?', '[\"Shifted\",\"Approved\",\"Authorized\",\"Followed\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(780, 18, 3, 'Analysis of preserved plants cataloged in the United States Virtual Herbarium indicates that rising temperatures correlate with earlier leaf production, but such specimens represent only brief moments in plants’ overall development. ______ this research with studies involving live plants would enable a fuller understanding of how these observed changes affect plant fitness.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"Foregrounding\",\"Categorizing\",\"Anticipating\",\"Complementing\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(781, 18, 4, 'Although Mistress and Maid, which depicts two women perusing a letter, is atypical of Johannes Vermeer’s genre paintings (scenes of everyday life) in that its subjects are set against a plain background instead of—as in Woman with a Pearl Necklace—a richly detailed one, the painting nonetheless ______ many signature traits of Vermeer’s art, including realistic rendering of natural light.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"evinces\",\"repudiates\",\"predates\",\"eschews\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(782, 18, 5, 'Technological advances have prompted companies to increasingly rely on automation to streamline production. Armin Granulo and colleagues, however, found that for products with higher symbolic value (those viewed as contributing to individual self-expression), consumers prefer products made by humans rather than by robots, likely because human-made products are more strongly associated with uniqueness. When considering automation, therefore, companies—especially those specializing in products of symbolic value—should weigh trade-offs between efficiency gains and consumer preferences.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It refers to a finding presented in the previous sentence to recommend that companies that value product quality reconsider automating their production processes.\",\"It emphasizes that a research finding discussed in the text has practical implications that are particularly relevant for businesses making a certain class of product.\",\"It presents evidence supporting the text’s argument that consumers prefer products with high symbolic value over products with low symbolic value.\",\"It illustrates the need for additional research to evaluate the claim in the previous sentence that automation affects how consumers evaluate products\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(783, 18, 6, 'The following text is from Yung Wing’s 1909 memoir My Life in China and America. Yung Wing was the first person from China to graduate from a US university.\n\nLittle did I realize when in 1845 I wrote, while in the Morrison school, a composition on “An Imaginary Voyage to New York and up the Hudson,” that I was to see New York in reality. This incident leads me to the reflection that sometimes our imagination foreshadows what lies uppermost in our minds and brings possibilities within the sphere of realities.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It indicates Yung’s unwillingness to distinguish between reality and fantasy as a child.\",\"It foreshadows Yung’s future difficulties in publishing his writings.\",\"It describes an event in Yung’s life that exemplifies a phenomenon.\",\"It illustrates the sense of adventure that Yung developed as a child.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(784, 18, 7, 'The prints in Images of Autonomous Matter, part of a traveling exhibition of innovative Japanese art from the 1960s and 1970s, exemplify the interest in creating minimalist images of stark materials, such as steel, that first emerged among Japanese printmakers in the mid-to-late twentieth century. Mitsuo Kano’s close-up of a serrated metal fragment, Soldered Blue, and Tatsuo Kawaguchi’s image of a single corroded staple, which belongs to his Relation—Quality series, are two such works in the exhibit. In their emphasis on the innate qualities of manufactured materials, both prints push traditional boundaries for figurative art.', 'Which statement about the prints by Kano and Kawaguchi in Images of Autonomous Matter is best supported by the text?', '[\"The portrayal of imperfection in the prints illustrates that the artist’s goal was to disrupt the carefully covered nature of most art exhibitions.\",\"The objects depicted and the manner of depiction render the prints distinct from more conventional works of art.\",\"The prints showcase how different methods for printing images can offer unique perspectives on stark materials.\",\"The prints emulate the style of an earlier artistic movement that used simplistic compositions and featured industrial objects.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(785, 18, 8, 'Radamés Cordero et al. have confirmed that twenty mushroom species (including Coprinellus micaceus and species from the genus Russula) maintain subambient temperatures in both their fruited bodies and their mycelium (the root-like hyphae from which the fruited bodies grow), though the benefits of this hypothermic behavior are unclear. Noting that relative coldness was more pronounced in fruiting than in nonfruiting sites of the mycelium—a difference that persisted even after fruited bodies were detached—the researchers speculate that thermoregulation in the mycelium may influence reproductive success.', 'Which statement about the mycelium of the twenty mushroom species is best supported by the text?', '[\"Variation in thermoregulation across the mycelium may occur independent of the presence or absence of fruited bodies.\",\"The correlation between higher mycelium temperature and greater fruit productivity indicates that successful reproduction may be dependent on thermoregulation in the mycelium.\",\"Temperatures in the fruiting areas of the mycelium are lower than in the nonfruiting areas due to differences in the depth and spread of the mycelium within soil or other organic matter.\",\"The mycelium generally maintains temperatures lower than those of the fruited bodies even when considering temperature variations between fruiting and nonfruiting sites.\"]', -1, 2, NULL, 'mcq', NULL, 'reading');
INSERT INTO `questions` (`id`, `test_id`, `question_number`, `passage`, `prompt`, `options`, `correct_answer_index`, `module`, `image_url`, `question_type`, `correct_answer_text`, `section`) VALUES
(786, 18, 9, 'The following text is from William Carlos Williams’s 1925 creative nonfiction book In the American Grain. Williams is discussing how works by nineteenth-century US poet and fiction writer Edgar Allan Poe were received by American readers.\n\nPoe must suffer by his originality. Invent that which is new, even if it be made of pine from your own yard, and there’s none to know what you have done. It is because there’s no name. This is the cause of Poe’s lack of recognition. He was American. He was the astounding, inconceivable growth of his locality. Gape at him they did, and he at them in amazement. Afterward with mutual hatred; he in disgust, they in mistrust. It is only that which is under your nose which seems inexplicable.', 'What does the text most strongly suggest about Poe’s work and American readers?', '[\"Poe’s work was so innovative that there was not even terminology to describe it, which led American readers to regard both the work and Poe himself as strange but quintessentially American.\",\"Poe’s work had few fans among American readers because it tended to present a negative image of American life and institutions.\",\"American readers largely ignored Poe’s work because its tone and subject matter were out of keeping with mainstream literature.\",\"American readers failed to appreciate Poe’s work because of its novelty and the fact that it reflected aspects of the American character too ingrained in those readers for them to comprehend.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(787, 18, 10, '<table class=\"passage-table\" border=\"1\" style=\"border-collapse: collapse; width: 100%; margin-bottom: 15px;\"><tr><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Common name</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average mass (kg)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Capable of flight?</th></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Lesser rhea</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">19.6</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">No</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Dalmatian pelican</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">11.5</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Yes</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Andean condor</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">11.3</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Yes</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Northern cassowary</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">44.0</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">No</td></tr></table>\n\nMost bird species that are capable of flight weigh less than a kilogram (kg), which is not surprising considering the burden that extra body weight puts on a flying animal. But not all flying birds are so light, as we can see most clearly in the example of the ______.', 'Which choice most effectively uses data from the table to complete the example?', '[\"northern cassowary, which has an average mass of 44.0 kg.\",\"Andean condor, which has an average mass below 10 kg.\",\"northern cassowary, which has a higher average mass than the lesser rhea.\",\"Dalmatian pelican, which has an average mass of 11.5 kg.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(788, 18, 11, 'The 2002 production of I’m Not Rappaport was the first Broadway show for which Teresa Snider-Stein was credited as a costume designer. Snider-Stein was among the Broadway costume designers interviewed by Sara Jablon-Roberts and Eulanda A. Sanders for their study of historical accuracy in costume design. They argue that aesthetics often outweigh fidelity to the past among designers for shows with historical settings. In a paper for a theater class, a student claims that the costume design for a modern production of Shakespeare’s A Midsummer Night’s Dream (set in ancient Greece) exemplifies this tendency.', 'Which quotation from the costume designer for the modern production of A Midsummer Night’s Dream would most effectively support the student’s claim?', '[\"“For A Midsummer Night’s Dream, I decided not to include the extra fabric that would have been typical of clothing in the period because it made the costumes unappealingly bulky.”\",\"“In trying to create the period look of A Midsummer Night’s Dream, I had to make some practical compromises, such as substituting cooler modern fabrics for historically accurate woolens so that the actors didn’t overheat.”\",\"“Although historically accurate costumes would have added an air of authenticity to A Midsummer Night’s Dream, they have so many layers that costume changes would have been difficult.”\",\"“The clothing of the period of A Midsummer Night’s Dream is aesthetically appealing but largely unfamiliar to today’s audiences, so minor deviations from historical accuracy largely went unnoticed.”\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(789, 18, 12, 'Studying animals in a laboratory allows variables to be systematically controlled, but removing animals from their wild habitats can affect their behavior and biology in unforeseen ways. Given this, biologists Rebecca M. Calisi-Rodriguez and George E. Bentley examined research on brown-throated three-toed sloths and canaries to see whether results from studies in the wild were consistent with the results of studies in the laboratory. Therefore, data showing that brown-throated three-toed sloths tend to sleep fewer than 10 hours per day in the wild would be irrelevant to Calisi-Rodriguez and Bentley\'s investigation if ______.', 'Which choice most logically completes the text?', '[\"this behavior pattern has not been studied in the lab.\",\"they tend to sleep more than 15 hours per day in the lab.\",\"the brains of male canaries show predictable seasonal changes in the wild.\",\"such data have been collected for canaries in laboratory settings but not in the wild.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(790, 18, 13, 'In 2008, the US state of Hawaii enacted rate stability regulations (RSRs), constraining insurance companies’ latitude to raise premiums (the periodic fees policyholders pay to maintain insurance policies) after policies are in effect. RSRs are effective at protecting existing policyholders from price volatility, but Naoki Aizawa and Ami Ko note that since dynamic pricing of premiums is an important risk-mitigation tool for insurers, RSRs may lead some insurers to scale back or entirely cease selling new policies in the affected market, thereby reducing the competitive pressure that typically restrains premium prices for new policies. Thus, Hawaii’s RSRs may ______.', 'Which choice most logically completes the text?', '[\"benefit policyholders at the expense of nonpolicyholders seeking to acquire policies.\",\"reduce premium price volatility once policies are in effect but increase risks for policyholders.\",\"prevent large increases in premium prices for new policies despite leading to fewer insurers offering such policies in the affected market.\",\"be more advantageous for insurers than they are for either current or prospective policyholders.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(791, 18, 14, 'In an analysis of medieval urbanization in Pisa, Greifswald, and other European settlements, researchers drew on modern urban scaling theory, which posits that population density in core urban areas increases as a city grows larger. Hypothesizing that this typical relationship would have differed in medieval settlements because of the constraining influence of strong hierarchical social structures (which are much less pronounced in modern cities) on social networking and economic integration—drivers of urban agglomeration—the team created a model that accounted for the presence of restrictive institutions. They found that the typically expected density-size relationship held for each of the 173 medieval settlements whose growth they analyzed, suggesting that ______.', 'Which choice most logically completes the text?', '[\"although there tends to be a positive relationship between population size and development of core urban areas for both medieval settlements and modern cities, social institutions likely limited the rate at which population density increased in medieval settlements.\",\"despite a change in the role of social structures over time, there is likely a notable consistency between medieval settlements and modern cities in underlying elements of the social and economic interactions among individuals that shape the development of core urban areas.\",\"the social and economic dynamics that affect urban agglomeration were likely much different in medieval settlements than in modern cities, despite the similarity across time in population density patterns.\",\"the constraining influence of hierarchical medieval institutions likely had a significant effect on individuals in some social groupings but little to no effect on members of other social groupings.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(792, 18, 15, 'Painter Georgette ______ for incorporating everyday objects from her Singaporean environment—such as lanterns, mooncakes, and tropical fruits—into her still-life compositions, was a pivotal figure in the mid-twentieth-century Nanyang art movement, which sought to blend European painting traditions (including still life) with elements of Southeast Asian cultures and art.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"Chen, was known\",\"Chen, known\",\"Chen was known\",\"Chen is known\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(793, 18, 16, '“Streetwide and bitter as hope / strewn between El Salvador and San Francisco.” These lines are from a poem by Chicano ______ whose early career as a campesino informs the dialogue on Mexican American politics and identity that unfolds in his work.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"writer Juan Felipe Herrera,\",\"writer, Juan Felipe Herrera\",\"writer, Juan Felipe Herrera,\",\"writer Juan Felipe Herrera\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(794, 18, 17, 'Los Angeles–based artist Henry Taylor\'s large, vibrant paintings of prominent Black figures such as Olympian Alice Coachman (See Alice Jump, 2011) and artist David Hammons (Hammons meets a hyena on holiday, ______ celebrated by admirers of twenty-first-century portraiture, attracted legions of new fans in 2024 when they were included in a popular Taylor retrospective at the Whitney Museum.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"2016), long\",\"2016) were long\",\"2016) have long been\",\"2016), had long been\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(795, 18, 18, 'Among the small magazines animating Boston’s vibrant literary scene in the early twentieth century was ______ by William Stanley Braithwaite and featuring poetry by John Gould Fletcher, Louis Untermeyer, and Richard Aldington; essays by Amy Lowell and Jeanette Marks; and reviews of recent books, this magazine publicized the work of influential avant-garde writers and artists of the day.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"the Poetry Review of America. Edited\",\"the Poetry Review of America; edited\",\"the Poetry Review of America, edited\",\"the Poetry Review of America edited\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(796, 18, 19, 'Reena Esmail\'s classical composition “Summitless Mountains” incorporates a raag, a melodic framework used in Hindustani classical music, called Raag Chandrakauns. Often, interplay between the raag\'s designated vadi and samvadi (the first- and second-most important notes, respectively) and its prescribed melodic sequences ______ an unsettled mood.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"have evoked\",\"evoke\",\"evokes\",\"evoking\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(797, 18, 20, 'Archived within the storied libraries of Timbuktu, a West African city prominent during the Songhai Empire, is The Pearls Leading to Accepted Guidance, one of the city\'s hundreds of thousands of historical manuscripts, each of which ______ researchers insight into Timbuktu\'s tenure as a center of trade and education.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"are offering\",\"offer\",\"offering\",\"offers\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(798, 18, 21, 'As anthropologist Cristina Grasseni explains, many artisanal cheeses in Italy, such as Provolone Valpadana from Trentino-Alto Adige and Ragusano from Sicily, are highly valued for their regional authenticity; ______ they are prized for being made using local ingredients and methods typical of their respective geographic regions.', 'Which choice completes the text with the most logical transition?', '[\"that is,\",\"still,\",\"rather,\",\"then,\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(799, 18, 22, 'The moon Leda orbits Jupiter in the same direction that the planet rotates. ______ Leda’s orbit is described as prograde. Ananke, another of Jupiter’s moons, orbits in the opposite direction, so its orbit is described with the opposite term: retrograde.', 'Which choice completes the text with the most logical transition?', '[\"In reality,\",\"Nevertheless,\",\"Hence,\",\"Next,\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(800, 18, 23, 'For several centuries after the birth of opera in sixteenth-century Florence, Italian remained the default language in which most opera scores were written. ______ opera singers today, such as the tenor Lawrence Brownlee, encounter a wide range of Italian terms—from affettuoso (with feeling) to affrettando (at a hurried tempo)—when following many eighteenth-century opera scores.', 'Which choice completes the text with the most logical transition?', '[\"Hence,\",\"Lastly,\",\"Granted,\",\"However,\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(801, 18, 24, 'Srivijaya, a Buddhist sea power based in Sumatra in Indonesia that reached the height of its influence around 800 CE, is classified as a thalassocracy. Thalassocracies are generally considered distinct from tellurocracies, or land-based powers. ______ the British Empire (1600s–1900s CE) notably extended its hegemony across both land and sea.', 'Which choice completes the text with the most logical transition?', '[\"Underscoring this difference,\",\"Exemplifying this distinction,\",\"Supporting this claim,\",\"Blurring this line,\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(802, 18, 25, 'According to climate envelope models, individual organisms that inhabit the coolest areas of their species’ geographic distribution are expected to benefit from a warming climate, while individuals in the warmest areas will struggle. A 2024 University of Arizona study, ______ found that warmer-than-average temperatures resulted in a decrease in growth across all areas of the common piñon tree\'s distribution range.', 'Which choice completes the text with the most logical transition?', '[\"though,\",\"therefore,\",\"for example,\",\"moreover,\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(803, 18, 26, 'While researching a topic, a student has taken the following notes:\n\nHyde Park is a 1931 color linocut print by Canadian artist Sybil Andrews.\n\nIt depicts a tranquil, everyday scene (a spring day in a city park).\n\nAmanzi Amthatha (“The cold water takes him”) is a 2001 black-and-white linocut print by South African artist Nomathemba Tana.\n\nIt features a scene with an explicitly political point of view (a Xhosa warrior fighting British colonial rule).\n\nRelief printing is a technique in which an image is carved onto a printing block, covered in ink or paint, and stamped onto paper.\n\nLino cutting is a type of relief printing that uses linoleum tile as the printing block.', 'The student wants to contrast the subject matter of the two prints. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"The print by Tana is a black-and-white linocut; by contrast, Andrews\'s is a relief print.\",\"Tana\'s print expresses an explicitly political point of view, while Andrews\'s depicts a tranquil, everyday scene.\",\"Andrews made Hyde Park in 1931, while Tana made Amanzi Amthatha (“The cold water takes him”) later, in 2001.\",\"The scenes depicted in both works were first carved onto a printing block, then stamped onto paper; however, one work is a linocut, while the other is a relief print.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(804, 18, 27, 'While researching a topic, a student has taken the following notes:\n\nFrancis Halzen is a Belgian particle physicist.\n\nParticle physicists study subatomic particles.\n\nNeutrinos are some of the least understood subatomic particles.\n\nNeutrinos were first discovered in the mid-twentieth century.\n\nHalzen is known for his discovery of high-energy astrophysical neutrinos.', 'The student wants to provide an example of a particle physicist whose research focuses on neutrinos. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"The research done on high-energy astrophysical neutrinos exemplifies the work particle physicists do to advance our understanding of subatomic particles.\",\"By studying high-energy astrophysical neutrinos—to name just one example—particle physicists can learn more about neutrinos.\",\"Particle physicist Francis Halzen is known for his discovery of high-energy astrophysical neutrinos.\",\"Neutrinos are a type of subatomic particle that particle physicists are still trying to understand.\"]', -1, 2, NULL, 'mcq', NULL, 'reading'),
(805, 19, 1, 'The following text is from Mark Twain\'s 1876 novel The Adventures of Tom Sawyer. Tom, a child, has been told by his aunt to paint their house\'s fence.\n\nTom appeared on the sidewalk with a bucket of whitewash and a long-handled brush. He surveyed the fence, and all gladness left him and a deep melancholy settled down upon his spirit. Thirty yards of board fence nine feet high.', 'As used in the text, what does the word “surveyed” most nearly mean?', '[\"Praised\",\"Organized\",\"Examined\",\"Converted\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(806, 19, 2, 'The influence of William Shakespeare\'s writings is clear in a vast range of subsequent literary works and is similarly ______ in many works in other media, from fine art (such as Edward Alcock\'s painting Portia and Shylock) to popular music (such as the musician Elvis Costello\'s song “Miss Macbeth”).', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"subtle\",\"apparent\",\"unusual\",\"excessive\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(807, 19, 3, 'The Apollo Moon landings (1969–1972) brought charged particle detectors and temperature probes to the Moon and produced large amounts of data, much of which was stored on technologies that are now obsolete. A data-transfer project is working to ______ these data so that the information is available to researcher Seichi Nagihara, who is investigating temperature changes on the Moon.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"improve\",\"simplify\",\"amend\",\"salvage\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(808, 19, 4, 'The following text is adapted from the 1895 poem “Ojistoh” by Emily Pauline Johnson, a Kanienkahagen (Mohawk) writer also known as Tekahionwake.\n\nI am Ojistoh, I am she, the wife\n\nOf him whose name breathes bravery and life\n\nAnd courage to the tribe who calls him chief.\n\nI am Ojistoh, his white star, and he\n\nIs land, and lake, and sky—and soul to me.', 'As used in the text, what does the word “breathes” most nearly mean?', '[\"Imparts\",\"Renounces\",\"Assents\",\"Absorbs\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(809, 19, 5, 'Mastering \'ajami, a Syrian art of creating intricately painted wood panels, demands a skill set that____innate talent: crafting the panels requires not just the ability to draw but also an understanding of traditional techniques, materials, and design elements, necessitating expertise gained through dedicated guidance from experienced artisans.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"restrains\",\"replicates\",\"characterizes\",\"transcends\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(810, 19, 6, 'In factories, humans and robots often work together. A research team ran an experiment to find out how working with robots affects relationships between human coworkers. The experiment included teams working together to make electric motor parts. One type of team included only humans and the other type included both humans and robots. Participants were paid for their work and were asked about their willingness to share their earnings with their human teammates. Participants from teams with robots were more likely to share with each other than participants from teams with only humans were.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It states the results of the experiment discussed in the text.\",\"It indicates the question that the study discussed in the text was meant to answer.\",\"It explains an important part of the design of the experiment discussed in the text.\",\"It illustrates a problem that inspired the study discussed in the text.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(811, 19, 7, 'Steve Carter’s award-winning play Eden was produced in 1976 by the groundbreaking Negro Ensemble Company (NEC). NEC cofounder Douglas Turner Ward, who worked as an actor, director, and playwright, had met actor and producer Robert Hooks while they were performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun. Together, they envisioned a theater company that would nurture and showcase the work of Black theater professionals. Since NEC’s founding in 1967, its workshops and performances have given Black playwrights, including Carter, a forum for their compelling stories.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It illustrates the widespread influence of a play discussed earlier in the text.\",\"It provides additional information about a person mentioned in the text.\",\"It emphasizes the ongoing significance of the theater company discussed in the text.\",\"It explains the circumstances that led to the formation of the theater company discussed in the text.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(812, 19, 8, 'Despite potential independent confirmation, the apparent detection in 2020 of phosphine (PH₃)—a gas that on Earth almost exclusively derives from biological sources—in Venus’s cloud deck remains controversial, in part because Venus is thought to be uninhabitable. To evaluate such a finding’s plausibility, William Bains et al. modeled multiple abiotic PH₃ pathways, including geochemical, atmospheric, and photochemical reactions, but none adequately explain the observed levels of PH₃. If Venusian PH₃ does exist, it would indicate insufficiencies in the current consensus on Venus’s chemistry.', 'Which choice best describes the overall structure of the text?', '[\"It introduces an unexpected observation of a particular gas in Venus’s atmosphere, presents an effort to investigate possible mechanisms that could explain that observation, and then notes an implication of that investigation’s findings.\",\"It explains why the consensus view of a particular gas in Venus’s atmosphere has recently become controversial, expands on a scientific team’s reasons for questioning that consensus, and then suggests that future observations of Venus’s atmosphere will likely be needed to settle the controversy.\",\"It compares the levels of a particular gas on Venus and Earth, sketches the chemical processes that account for differences in these levels, and then addresses some of the practical challenges of studying the presence of this gas on Venus more closely.\",\"It outlines recent efforts to confirm the presence of a particular gas in Venus’s atmosphere, summarizes a research team’s evaluations of those efforts’ methodological shortcomings, and then explains why that team remains skeptical of the gas’s future detection.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(813, 19, 9, 'Given the immense scope of space, the search for extraterrestrial life is almost necessarily concentrated on the exoplanets deemed to have the most plausible chance of success—typically, atmosphere-bearing terrestrial planets orbiting within a certain range of their stars (termed the habitable zone). Claiming that Earth experienced a long transition from single-lid to plate tectonics that accelerated the emergence and evolution of complex organisms, researchers Robert J. Stern and Taras V. Gerya hold that consideration of tectonics, an often overlooked factor, could help further narrow the search for advanced extraterrestrial species.', 'Based on the text, what do Stern and Gerya most likely believe about the development of complex life on exoplanets?', '[\"It is more likely to occur on habitable zone planets with atmospheres and plate tectonics than on otherwise similar planets that lack plate tectonics.\",\"It is more likely to occur if habitable zone planets with atmospheres transition from single-lid to plate tectonics late in their history than if they transition early in their history.\",\"It is probably more dependent on the presence of plate tectonics than on orbital distance from a host star or the presence of an atmosphere.\",\"It is unlikely unless the transition from single-lid to plate tectonics occurs before the acquisition of a lasting atmosphere.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(814, 19, 10, 'Quality assessments of concrete typically focus almost exclusively on compressive strength as a measure of durability, overlooking other potentially relevant factors. Licsa Ptacek et al. therefore investigated the potential of gas permeability (vulnerability to incursion by gases), which is caused in part by excessive porosity, as a durability indicator. Their measurements and observations revealed that quality of conditions during the concrete curing phase negatively correlates with gas permeability and that high gas permeability values are associated with increased deterioration as concrete surfaces age.', 'Information in the text best supports which statement about Ptacek et al.’s findings?', '[\"They suggest that gas permeability testing presents a more reliable indication of concrete durability than compressive strength testing does.\",\"They bolster the claim that concrete’s susceptibility to damage decreases as its gas permeability increases.\",\"They call into question the idea that quality of curing conditions directly affects concrete gas permeability but is unrelated to compressive strength.\",\"They indicate that evaluation of gas permeability is an appropriate addition to concrete quality assessment procedures.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(815, 19, 11, 'The Wonderful Wizard of Oz is a 1900 novel by L. Frank Baum. In the novel, Dorothy, who is from Kansas, finds herself in an unfamiliar place called Oz. Kansas is presented as being less appealing than Oz, as is clear when ______.', 'Which quotation from The Wonderful Wizard of Oz most effectively illustrates the claim?', '[\"a character says to Dorothy, “I cannot understand why you should wish to leave this beautiful country and go back to the dry, gray place you call Kansas.”\",\"a character says to others, “But it will take more than imagination to carry Dorothy back to Kansas, and I’m sure I don’t know how it can be done.”\",\"the narrator states, “Dorothy did not feel nearly so bad as you might think a little girl would who had been suddenly whisked away from her own country and set down in the midst of a strange land.”\",\"the narrator states, “Before them was a great stretch of country having a floor as smooth and shining and white as the bottom of a big platter.”\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(816, 19, 12, '<table class=\"passage-table\" border=\"1\" style=\"border-collapse: collapse; width: 100%; margin-bottom: 15px;\"><tr><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Month</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average high (°F)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average low (°F)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average male wing centroid size (mm)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average female wing centroid size (mm)</th></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">October</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">67</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">44</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">1.98</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.29</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">July</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">87</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">62</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.02</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.31</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">June</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">80</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">56</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.01</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.31</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">May</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">73</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">50</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">1.98</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">2.27</td></tr></table>\n\nDrosophila (fruit flies) have generation times of 10–12 days, so seasonal changes in humidity and other environmental conditions can drive seasonal fluctuations in chromosome rearrangements in species such as D. persimilis and D. mediopunctata. Drosophila body size (for which wing centroid size serves as a proxy measure) correlates with life span. Banu Sebnem Önder and Cansu Fidan Aksoy measured the wing sizes of members of a D. melanogaster population in Yesilöz, Turkey, that were collected monthly between May and October over three years. Their research suggests that Drosophila collected in relatively cooler months should tend to have a shorter life span, as is illustrated by the finding that ______.', 'Which choice most effectively uses data from the table to complete the assertion?', '[\"the average female wing centroid size was smaller in May than in June.\",\"the average male wing centroid size was consistently smaller than the average female wing centroid size in all four months in the table.\",\"the average monthly low temperature was lower in May than in June.\",\"the average male wing centroid size was 1.98 mm in May but was 2.31 mm in July.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(817, 19, 13, 'Rafael Núñez and colleagues studied how members of the Yupno, an Indigenous group in Papua New Guinea, conceptualize time in both spoken language and gestures. The researchers recorded Yupno speakers explaining certain temporal words and phrases, such as jare, a past-oriented expression that translates to “day before yesterday,” and coded each speaker’s manual gestures. Previous research has found a tendency in many cultures to make temporal distinctions along imagined linear axes: for instance, Hebrew speakers often refer to the right/left axis to describe events in time. Some researchers believe this tendency is universal, but Núñez and colleagues claim this is not the case.', 'Which finding, if true, would most directly support Núñez and colleagues’ claim?', '[\"Yupno speakers typically use their left hand to make temporal gestures regardless of whether the gestures are past oriented or future oriented.\",\"Future-oriented gestures used by Yupno speakers do not, on average, point in the opposite linear direction of past-oriented gestures.\",\"Some Yupno grammatical structures used when talking about time are also used in Hebrew.\",\"Yupno speakers were observed making temporal gestures both indoors and outdoors, though with greater frequency when indoors.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(818, 19, 14, 'The Man–Made World: Or, Our Androcentric Culture is a 1911 nonfiction work by Charlotte Perkins Gilman. In the text, the author emphasizes the importance of cultivating individuals rather than comparing them: ______.', 'Which quotation from The Man–Made World: Or, Our Androcentric Culture most effectively illustrates the claim?', '[\"“That every child on earth shall have right conditions to make the best growth possible to it; that every citizen, from birth to death, shall have a chance to learn all he or she can, to develop every power that is in them.”\",\"“We do not sadly measure the cabbage–stalk by the corn–stalk, and praise the corn for getting ahead of the cabbage—nor incite the cabbage to imitate the corn. We nourish both, to its best growth—and are the richer.”\",\"“We have but to learn the real elements in humanity; its true powers and natural characteristics.”\",\"“We are now to consider the growth of the family in humanity.”\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(819, 19, 15, 'Zooarchaeologist Ophélie Lebrasseur and her team examined a fox skeleton discovered in 1991 at an archaeological site alongside artifacts of human habitation (like spear points) in central Argentina. Lebrasseur et al. determined that the fox was Dusicyon avus, an extinct species resembling a jackal, and radiocarbon dating placed the fox at the site at the same time as human inhabitants. (Indeed, the inhabitants may have deliberately buried the fox.) In addition, while wild foxes have a diet entirely made of meat, isotopic signatures of the skeleton’s teeth indicated that the fox\'s diet, like that of the humans, was partly composed of plant material. Lebrasseur et al. therefore concluded that ______.', 'Which choice most logically completes the text?', '[\"the humans who were alive at the same time as the fox most likely ate more meat than the fox did.\",\"the fox had a diet more similar to that of jackals than to that of wild foxes.\",\"the humans who were alive at the same time as the fox hunted using the spears whose points were also found at the site.\",\"the fox may have been a companion animal of the humans who inhabited the site at the same time.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(820, 19, 16, 'In the nineteenth century, Elizabeth Cady Stanton and Susan B. Anthony ______ for women’s right to vote in the United States.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"having campaigned\",\"campaigned\",\"campaigning\",\"to campaign\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(821, 19, 17, 'While conducting an interview for her book Latina Authors and Their Muses, editor Mayra Calvani asked Sarah Cortez, author of the memoir Walking Home, what ______ Cortez\'s response was Bury Me Deep by Megan Abbott.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"her favorite book was.\",\"was her favorite book?\",\"her favorite book was?\",\"was her favorite book!\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(822, 19, 18, 'Choreographers George Balanchine and Martha Graham both contributed sections to the dance piece Episodes, which premiered at New York’s City Center of Music and Drama in 1959. This cross-genre collaboration brought together the distinct features of Balanchine’s neoclassical ballet and Graham’s modern ______ the stylistic diversity and creative innovation within the dance world.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"dance, it showcased\",\"dance. Which showcased\",\"dance, showcasing\",\"dance. Showcasing\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(823, 19, 19, 'In the book A Theory of Harmony (1985), Swiss musicologist Ernst Levy argued that every chord has an opposite that can be substituted for it. For example, a pianist could replace the vi chord for the III chord while ______ chord is a given chord\'s opposite can be determined using a music visualization tool called the circle of fifths.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"improvising which\",\"improvising and which\",\"improvising. Which\",\"improvising, which\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(824, 19, 20, 'In her Silueta sculpture series, the Cuban American artist Ana ______ to access what she called an “omnipresent female force,” utilized a variety of natural materials to create outlines—or silhouettes—of her own body.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"Mendieta was hoping\",\"Mendieta hoped\",\"Mendieta had hoped\",\"Mendieta, hoping\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(825, 19, 21, 'As volcanologists like Tamsin Mather are apt to make clear, not all volcanoes are the same. Tendürek in Turkey, for example, is a shield volcano, a type of volcano named for its low profile, resembling a warrior\'s shield lying on the ground. Opala in Russia, ______ is a caldera, a large cauldron-like hollow that forms shortly after the emptying of a magma chamber in a volcanic eruption.', 'Which choice completes the text with the most logical transition?', '[\"in any case,\",\"in contrast,\",\"in conclusion,\",\"in fact,\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(826, 19, 22, 'The United Nations’ Trade and Development organization divides exports into five key categories: food items, agricultural materials, fuels, ores and raw metals, and manufactured goods (i.e., most nonfood goods made by machinery or by hand). In 2022, the majority (62 percent) of Belgium\'s exports were manufactured goods. ______ vaccines, medicines, and cars were its top exports.', 'Which choice completes the text with the most logical transition?', '[\"In a broader sense,\",\"Within this category,\",\"In the future,\",\"Despite this majority,\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(827, 19, 23, 'A research team led by Gal Badihi has discovered that chimpanzees communicate through exchanges of gestures occurring at a pace similar to that of human conversations. ______ chimpanzee gesture exchanges have short pauses of about 120 milliseconds between communications, comparable to the 200-millisecond average pause between turns in human speech.', 'Which choice completes the text with the most logical transition?', '[\"Specifically,\",\"As a result,\",\"By contrast,\",\"Nevertheless,\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(828, 19, 24, 'While researching a topic, a student has taken the following notes:\n\nThe Great Salt Lake in Utah is one of the world\'s saltiest bodies of water.\n\nThe northern portion of the lake has a higher concentration of salt than the southern portion.\n\nAquatic insects called Ephydra cinerea live in the southern portion.\n\nBacteria called Nodularia live in the southern portion.', 'The student wants to emphasize a difference between Ephydra cinerea and Nodularia. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"Ephydra cinerea and Nodularia are different types of organisms: Ephydra cinerea are aquatic insects, whereas Nodularia are bacteria.\",\"The northern portion of the Great Salt Lake has a higher concentration of salt than does the southern portion.\",\"Ephydra cinerea and Nodularia both live in the Great Salt Lake\'s southern portion.\",\"Ephydra cinerea are aquatic insects that live in the southern portion of the Great Salt Lake.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(829, 19, 25, 'While researching a topic, a student has taken the following notes:\n\nExtravehicular activities (EVAs) are activities performed outside a spacecraft by astronauts in outer space.\n\nEVAs are also known as spacewalks.\n\nRichard Mastracchio is a former US astronaut who has performed 9 spacewalks.\n\nThe total time of Mastracchio\'s spacewalks was 53 hours and 4 minutes.\n\nGarrett Reisman is a former US astronaut who has performed 3 spacewalks.\n\nThe total time of Reisman\'s spacewalks was 21 hours and 21 minutes.', 'The student wants to emphasize a similarity between the astronauts Mastracchio and Reisman. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"Reisman has spent less time performing spacewalks than Mastracchio has.\",\"EVAs, also known as spacewalks, are activities done by astronauts outside a spacecraft.\",\"Mastracchio and Reisman have each performed multiple spacewalks.\",\"Mastracchio has performed spacewalks, but Reisman has performed EVAs.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(830, 19, 26, 'While researching a topic, a student has taken the following notes:\n\nThe Tijuana Slough National Wildlife Refuge (NWR) is a protected natural area in California.\n\nIt encompasses 1,023 acres.\n\nThe Tijuana Slough NWR was established to safeguard the habitat of the light-footed clapper rail, an endangered species.\n\nThe Tijuana Slough NWR is managed by the US Fish & Wildlife Service.\n\nThe US Fish & Wildlife Service limits human activities in the area.', 'The student wants to emphasize the role the US Fish & Wildlife Service plays in safeguarding the habitat of the light-footed clapper rail. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"By limiting human activities in the Tijuana Slough NWR, the US Fish & Wildlife Service safeguards the habitat of the light-footed clapper rail.\",\"Human activities are limited in the Tijuana Slough NWR, a protected natural area in California.\",\"Home to the light-footed clapper rail, the Tijuana Slough NWR is located in California, where it encompasses 1,023 acres.\",\"The 1,023-acre Tijuana Slough NWR was established to safeguard the habitat of the light-footed clapper rail, an endangered species.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(831, 19, 27, 'While researching a topic, a student has taken the following notes:\n\nThe cuneiform script is the earliest known set of symbols used for writing.\n\nSumerian was one of the first languages to be written using the cuneiform script.\n\nSumerian was a language in ancient Mesopotamia (present-day Iraq).\n\nClay tablets with Sumerian writing have been found there.\n\nSome of these tablets are almost 5,000 years old.', 'The student wants to identify a language that was written using the cuneiform script. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"Examples of Mesopotamian writing that are nearly 5,000 years old have been found.\",\"A language in ancient Mesopotamia used the cuneiform script for writing.\",\"Clay tablets with cuneiform script have been found in present-day Iraq.\",\"Sumerian, an ancient Mesopotamian language, was written using the cuneiform script.\"]', 1, 1, NULL, 'mcq', NULL, 'reading'),
(832, 19, 1, 'Zygomorphic (bilaterally symmetric) flowers remain open and functional on average 1.1 days longer than actinomorphic (radially symmetric) flowers do. Ruby E. Stephens and colleagues claim that this extended period could be ______ the relatively small pool of potential pollinators available to zygomorphic flowers and the greater chance at successful pollination that remaining open affords them.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"analogous to\",\"magnified by\",\"converted by\",\"attributed to\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(833, 19, 2, 'The following text is from Charles Dickens’s 1861 novel Great Expectations. The narrator is taking a walk near his home on a damp morning.\n\nOn every rail and gate, wet lay clammy, and the marsh mist was so thick, that the wooden finger on the post directing people to our village—a direction which they never accepted, for they never came there—was invisible to me until I was quite close under it.', 'As used in the text, what does the word “accepted” most nearly mean?', '[\"Shifted\",\"Approved\",\"Authorized\",\"Followed\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(834, 19, 3, 'Analysis of preserved plants cataloged in the United States Virtual Herbarium indicates that rising temperatures correlate with earlier leaf production, but such specimens represent only brief moments in plants’ overall development. ______ this research with studies involving live plants would enable a fuller understanding of how these observed changes affect plant fitness.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"Foregrounding\",\"Categorizing\",\"Anticipating\",\"Complementing\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(835, 19, 4, 'Although Mistress and Maid, which depicts two women perusing a letter, is atypical of Johannes Vermeer’s genre paintings (scenes of everyday life) in that its subjects are set against a plain background instead of—as in Woman with a Pearl Necklace—a richly detailed one, the painting nonetheless ______ many signature traits of Vermeer’s art, including realistic rendering of natural light.', 'Which choice completes the text with the most logical and precise word or phrase?', '[\"evinces\",\"repudiates\",\"predates\",\"eschews\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(836, 19, 5, 'Technological advances have prompted companies to increasingly rely on automation to streamline production. Armin Granulo and colleagues, however, found that for products with higher symbolic value (those viewed as contributing to individual self-expression), consumers prefer products made by humans rather than by robots, likely because human-made products are more strongly associated with uniqueness. When considering automation, therefore, companies—especially those specializing in products of symbolic value—should weigh trade-offs between efficiency gains and consumer preferences.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It refers to a finding presented in the previous sentence to recommend that companies that value product quality reconsider automating their production processes.\",\"It emphasizes that a research finding discussed in the text has practical implications that are particularly relevant for businesses making a certain class of product.\",\"It presents evidence supporting the text’s argument that consumers prefer products with high symbolic value over products with low symbolic value.\",\"It illustrates the need for additional research to evaluate the claim in the previous sentence that automation affects how consumers evaluate products\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(837, 19, 6, 'The following text is from Yung Wing’s 1909 memoir My Life in China and America. Yung Wing was the first person from China to graduate from a US university.\n\nLittle did I realize when in 1845 I wrote, while in the Morrison school, a composition on “An Imaginary Voyage to New York and up the Hudson,” that I was to see New York in reality. This incident leads me to the reflection that sometimes our imagination foreshadows what lies uppermost in our minds and brings possibilities within the sphere of realities.', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '[\"It indicates Yung’s unwillingness to distinguish between reality and fantasy as a child.\",\"It foreshadows Yung’s future difficulties in publishing his writings.\",\"It describes an event in Yung’s life that exemplifies a phenomenon.\",\"It illustrates the sense of adventure that Yung developed as a child.\"]', 1, 2, NULL, 'mcq', NULL, 'reading');
INSERT INTO `questions` (`id`, `test_id`, `question_number`, `passage`, `prompt`, `options`, `correct_answer_index`, `module`, `image_url`, `question_type`, `correct_answer_text`, `section`) VALUES
(838, 19, 7, 'The prints in Images of Autonomous Matter, part of a traveling exhibition of innovative Japanese art from the 1960s and 1970s, exemplify the interest in creating minimalist images of stark materials, such as steel, that first emerged among Japanese printmakers in the mid-to-late twentieth century. Mitsuo Kano’s close-up of a serrated metal fragment, Soldered Blue, and Tatsuo Kawaguchi’s image of a single corroded staple, which belongs to his Relation—Quality series, are two such works in the exhibit. In their emphasis on the innate qualities of manufactured materials, both prints push traditional boundaries for figurative art.', 'Which statement about the prints by Kano and Kawaguchi in Images of Autonomous Matter is best supported by the text?', '[\"The portrayal of imperfection in the prints illustrates that the artist’s goal was to disrupt the carefully covered nature of most art exhibitions.\",\"The objects depicted and the manner of depiction render the prints distinct from more conventional works of art.\",\"The prints showcase how different methods for printing images can offer unique perspectives on stark materials.\",\"The prints emulate the style of an earlier artistic movement that used simplistic compositions and featured industrial objects.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(839, 19, 8, 'Radamés Cordero et al. have confirmed that twenty mushroom species (including Coprinellus micaceus and species from the genus Russula) maintain subambient temperatures in both their fruited bodies and their mycelium (the root-like hyphae from which the fruited bodies grow), though the benefits of this hypothermic behavior are unclear. Noting that relative coldness was more pronounced in fruiting than in nonfruiting sites of the mycelium—a difference that persisted even after fruited bodies were detached—the researchers speculate that thermoregulation in the mycelium may influence reproductive success.', 'Which statement about the mycelium of the twenty mushroom species is best supported by the text?', '[\"Variation in thermoregulation across the mycelium may occur independent of the presence or absence of fruited bodies.\",\"The correlation between higher mycelium temperature and greater fruit productivity indicates that successful reproduction may be dependent on thermoregulation in the mycelium.\",\"Temperatures in the fruiting areas of the mycelium are lower than in the nonfruiting areas due to differences in the depth and spread of the mycelium within soil or other organic matter.\",\"The mycelium generally maintains temperatures lower than those of the fruited bodies even when considering temperature variations between fruiting and nonfruiting sites.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(840, 19, 9, 'The following text is from William Carlos Williams’s 1925 creative nonfiction book In the American Grain. Williams is discussing how works by nineteenth-century US poet and fiction writer Edgar Allan Poe were received by American readers.\n\nPoe must suffer by his originality. Invent that which is new, even if it be made of pine from your own yard, and there’s none to know what you have done. It is because there’s no name. This is the cause of Poe’s lack of recognition. He was American. He was the astounding, inconceivable growth of his locality. Gape at him they did, and he at them in amazement. Afterward with mutual hatred; he in disgust, they in mistrust. It is only that which is under your nose which seems inexplicable.', 'What does the text most strongly suggest about Poe’s work and American readers?', '[\"Poe’s work was so innovative that there was not even terminology to describe it, which led American readers to regard both the work and Poe himself as strange but quintessentially American.\",\"Poe’s work had few fans among American readers because it tended to present a negative image of American life and institutions.\",\"American readers largely ignored Poe’s work because its tone and subject matter were out of keeping with mainstream literature.\",\"American readers failed to appreciate Poe’s work because of its novelty and the fact that it reflected aspects of the American character too ingrained in those readers for them to comprehend.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(841, 19, 10, '<table class=\"passage-table\" border=\"1\" style=\"border-collapse: collapse; width: 100%; margin-bottom: 15px;\"><tr><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Common name</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Average mass (kg)</th><th style=\"border: 1px solid #cbd5e1; padding: 8px; background-color: #f8fafc; font-weight: bold; text-align: left;\">Capable of flight?</th></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Lesser rhea</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">19.6</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">No</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Dalmatian pelican</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">11.5</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Yes</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Andean condor</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">11.3</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Yes</td></tr><tr><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">Northern cassowary</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">44.0</td><td style=\"border: 1px solid #cbd5e1; padding: 8px; text-align: left;\">No</td></tr></table>\n\nMost bird species that are capable of flight weigh less than a kilogram (kg), which is not surprising considering the burden that extra body weight puts on a flying animal. But not all flying birds are so light, as we can see most clearly in the example of the ______.', 'Which choice most effectively uses data from the table to complete the example?', '[\"northern cassowary, which has an average mass of 44.0 kg.\",\"Andean condor, which has an average mass below 10 kg.\",\"northern cassowary, which has a higher average mass than the lesser rhea.\",\"Dalmatian pelican, which has an average mass of 11.5 kg.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(842, 19, 11, 'The 2002 production of I’m Not Rappaport was the first Broadway show for which Teresa Snider-Stein was credited as a costume designer. Snider-Stein was among the Broadway costume designers interviewed by Sara Jablon-Roberts and Eulanda A. Sanders for their study of historical accuracy in costume design. They argue that aesthetics often outweigh fidelity to the past among designers for shows with historical settings. In a paper for a theater class, a student claims that the costume design for a modern production of Shakespeare’s A Midsummer Night’s Dream (set in ancient Greece) exemplifies this tendency.', 'Which quotation from the costume designer for the modern production of A Midsummer Night’s Dream would most effectively support the student’s claim?', '[\"“For A Midsummer Night’s Dream, I decided not to include the extra fabric that would have been typical of clothing in the period because it made the costumes unappealingly bulky.”\",\"“In trying to create the period look of A Midsummer Night’s Dream, I had to make some practical compromises, such as substituting cooler modern fabrics for historically accurate woolens so that the actors didn’t overheat.”\",\"“Although historically accurate costumes would have added an air of authenticity to A Midsummer Night’s Dream, they have so many layers that costume changes would have been difficult.”\",\"“The clothing of the period of A Midsummer Night’s Dream is aesthetically appealing but largely unfamiliar to today’s audiences, so minor deviations from historical accuracy largely went unnoticed.”\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(843, 19, 12, 'Studying animals in a laboratory allows variables to be systematically controlled, but removing animals from their wild habitats can affect their behavior and biology in unforeseen ways. Given this, biologists Rebecca M. Calisi-Rodriguez and George E. Bentley examined research on brown-throated three-toed sloths and canaries to see whether results from studies in the wild were consistent with the results of studies in the laboratory. Therefore, data showing that brown-throated three-toed sloths tend to sleep fewer than 10 hours per day in the wild would be irrelevant to Calisi-Rodriguez and Bentley\'s investigation if ______.', 'Which choice most logically completes the text?', '[\"this behavior pattern has not been studied in the lab.\",\"they tend to sleep more than 15 hours per day in the lab.\",\"the brains of male canaries show predictable seasonal changes in the wild.\",\"such data have been collected for canaries in laboratory settings but not in the wild.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(844, 19, 13, 'In 2008, the US state of Hawaii enacted rate stability regulations (RSRs), constraining insurance companies’ latitude to raise premiums (the periodic fees policyholders pay to maintain insurance policies) after policies are in effect. RSRs are effective at protecting existing policyholders from price volatility, but Naoki Aizawa and Ami Ko note that since dynamic pricing of premiums is an important risk-mitigation tool for insurers, RSRs may lead some insurers to scale back or entirely cease selling new policies in the affected market, thereby reducing the competitive pressure that typically restrains premium prices for new policies. Thus, Hawaii’s RSRs may ______.', 'Which choice most logically completes the text?', '[\"benefit policyholders at the expense of nonpolicyholders seeking to acquire policies.\",\"reduce premium price volatility once policies are in effect but increase risks for policyholders.\",\"prevent large increases in premium prices for new policies despite leading to fewer insurers offering such policies in the affected market.\",\"be more advantageous for insurers than they are for either current or prospective policyholders.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(845, 19, 14, 'In an analysis of medieval urbanization in Pisa, Greifswald, and other European settlements, researchers drew on modern urban scaling theory, which posits that population density in core urban areas increases as a city grows larger. Hypothesizing that this typical relationship would have differed in medieval settlements because of the constraining influence of strong hierarchical social structures (which are much less pronounced in modern cities) on social networking and economic integration—drivers of urban agglomeration—the team created a model that accounted for the presence of restrictive institutions. They found that the typically expected density-size relationship held for each of the 173 medieval settlements whose growth they analyzed, suggesting that ______.', 'Which choice most logically completes the text?', '[\"although there tends to be a positive relationship between population size and development of core urban areas for both medieval settlements and modern cities, social institutions likely limited the rate at which population density increased in medieval settlements.\",\"despite a change in the role of social structures over time, there is likely a notable consistency between medieval settlements and modern cities in underlying elements of the social and economic interactions among individuals that shape the development of core urban areas.\",\"the social and economic dynamics that affect urban agglomeration were likely much different in medieval settlements than in modern cities, despite the similarity across time in population density patterns.\",\"the constraining influence of hierarchical medieval institutions likely had a significant effect on individuals in some social groupings but little to no effect on members of other social groupings.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(846, 19, 15, 'Painter Georgette ______ for incorporating everyday objects from her Singaporean environment—such as lanterns, mooncakes, and tropical fruits—into her still-life compositions, was a pivotal figure in the mid-twentieth-century Nanyang art movement, which sought to blend European painting traditions (including still life) with elements of Southeast Asian cultures and art.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"Chen, was known\",\"Chen, known\",\"Chen was known\",\"Chen is known\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(847, 19, 16, '“Streetwide and bitter as hope / strewn between El Salvador and San Francisco.” These lines are from a poem by Chicano ______ whose early career as a campesino informs the dialogue on Mexican American politics and identity that unfolds in his work.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"writer Juan Felipe Herrera,\",\"writer, Juan Felipe Herrera\",\"writer, Juan Felipe Herrera,\",\"writer Juan Felipe Herrera\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(848, 19, 17, 'Los Angeles–based artist Henry Taylor\'s large, vibrant paintings of prominent Black figures such as Olympian Alice Coachman (See Alice Jump, 2011) and artist David Hammons (Hammons meets a hyena on holiday, ______ celebrated by admirers of twenty-first-century portraiture, attracted legions of new fans in 2024 when they were included in a popular Taylor retrospective at the Whitney Museum.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"2016), long\",\"2016) were long\",\"2016) have long been\",\"2016), had long been\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(849, 19, 18, 'Among the small magazines animating Boston’s vibrant literary scene in the early twentieth century was ______ by William Stanley Braithwaite and featuring poetry by John Gould Fletcher, Louis Untermeyer, and Richard Aldington; essays by Amy Lowell and Jeanette Marks; and reviews of recent books, this magazine publicized the work of influential avant-garde writers and artists of the day.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"the Poetry Review of America. Edited\",\"the Poetry Review of America; edited\",\"the Poetry Review of America, edited\",\"the Poetry Review of America edited\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(850, 19, 19, 'Reena Esmail\'s classical composition “Summitless Mountains” incorporates a raag, a melodic framework used in Hindustani classical music, called Raag Chandrakauns. Often, interplay between the raag\'s designated vadi and samvadi (the first- and second-most important notes, respectively) and its prescribed melodic sequences ______ an unsettled mood.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"have evoked\",\"evoke\",\"evokes\",\"evoking\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(851, 19, 20, 'Archived within the storied libraries of Timbuktu, a West African city prominent during the Songhai Empire, is The Pearls Leading to Accepted Guidance, one of the city\'s hundreds of thousands of historical manuscripts, each of which ______ researchers insight into Timbuktu\'s tenure as a center of trade and education.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[\"are offering\",\"offer\",\"offering\",\"offers\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(852, 19, 21, 'As anthropologist Cristina Grasseni explains, many artisanal cheeses in Italy, such as Provolone Valpadana from Trentino-Alto Adige and Ragusano from Sicily, are highly valued for their regional authenticity; ______ they are prized for being made using local ingredients and methods typical of their respective geographic regions.', 'Which choice completes the text with the most logical transition?', '[\"that is,\",\"still,\",\"rather,\",\"then,\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(853, 19, 22, 'The moon Leda orbits Jupiter in the same direction that the planet rotates. ______ Leda’s orbit is described as prograde. Ananke, another of Jupiter’s moons, orbits in the opposite direction, so its orbit is described with the opposite term: retrograde.', 'Which choice completes the text with the most logical transition?', '[\"In reality,\",\"Nevertheless,\",\"Hence,\",\"Next,\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(854, 19, 23, 'For several centuries after the birth of opera in sixteenth-century Florence, Italian remained the default language in which most opera scores were written. ______ opera singers today, such as the tenor Lawrence Brownlee, encounter a wide range of Italian terms—from affettuoso (with feeling) to affrettando (at a hurried tempo)—when following many eighteenth-century opera scores.', 'Which choice completes the text with the most logical transition?', '[\"Hence,\",\"Lastly,\",\"Granted,\",\"However,\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(855, 19, 24, 'Srivijaya, a Buddhist sea power based in Sumatra in Indonesia that reached the height of its influence around 800 CE, is classified as a thalassocracy. Thalassocracies are generally considered distinct from tellurocracies, or land-based powers. ______ the British Empire (1600s–1900s CE) notably extended its hegemony across both land and sea.', 'Which choice completes the text with the most logical transition?', '[\"Underscoring this difference,\",\"Exemplifying this distinction,\",\"Supporting this claim,\",\"Blurring this line,\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(856, 19, 25, 'According to climate envelope models, individual organisms that inhabit the coolest areas of their species’ geographic distribution are expected to benefit from a warming climate, while individuals in the warmest areas will struggle. A 2024 University of Arizona study, ______ found that warmer-than-average temperatures resulted in a decrease in growth across all areas of the common piñon tree\'s distribution range.', 'Which choice completes the text with the most logical transition?', '[\"though,\",\"therefore,\",\"for example,\",\"moreover,\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(857, 19, 26, 'While researching a topic, a student has taken the following notes:\n\nHyde Park is a 1931 color linocut print by Canadian artist Sybil Andrews.\n\nIt depicts a tranquil, everyday scene (a spring day in a city park).\n\nAmanzi Amthatha (“The cold water takes him”) is a 2001 black-and-white linocut print by South African artist Nomathemba Tana.\n\nIt features a scene with an explicitly political point of view (a Xhosa warrior fighting British colonial rule).\n\nRelief printing is a technique in which an image is carved onto a printing block, covered in ink or paint, and stamped onto paper.\n\nLino cutting is a type of relief printing that uses linoleum tile as the printing block.', 'The student wants to contrast the subject matter of the two prints. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"The print by Tana is a black-and-white linocut; by contrast, Andrews\'s is a relief print.\",\"Tana\'s print expresses an explicitly political point of view, while Andrews\'s depicts a tranquil, everyday scene.\",\"Andrews made Hyde Park in 1931, while Tana made Amanzi Amthatha (“The cold water takes him”) later, in 2001.\",\"The scenes depicted in both works were first carved onto a printing block, then stamped onto paper; however, one work is a linocut, while the other is a relief print.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(858, 19, 27, 'While researching a topic, a student has taken the following notes:\n\nFrancis Halzen is a Belgian particle physicist.\n\nParticle physicists study subatomic particles.\n\nNeutrinos are some of the least understood subatomic particles.\n\nNeutrinos were first discovered in the mid-twentieth century.\n\nHalzen is known for his discovery of high-energy astrophysical neutrinos.', 'The student wants to provide an example of a particle physicist whose research focuses on neutrinos. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '[\"The research done on high-energy astrophysical neutrinos exemplifies the work particle physicists do to advance our understanding of subatomic particles.\",\"By studying high-energy astrophysical neutrinos—to name just one example—particle physicists can learn more about neutrinos.\",\"Particle physicist Francis Halzen is known for his discovery of high-energy astrophysical neutrinos.\",\"Neutrinos are a type of subatomic particle that particle physicists are still trying to understand.\"]', 1, 2, NULL, 'mcq', NULL, 'reading'),
(859, 19, 1, NULL, 'An artist made 12 pieces of pottery using 42 pounds of clay. The pottery included only bowls and vases. Each bowl used 2 pounds of clay and each vase used 4 pounds of clay. How many vases did the artist make?', '[\"3\",\"5\",\"7\",\"9\"]', 3, 1, NULL, 'mcq', NULL, 'math'),
(860, 19, 2, NULL, 'One gallon of paint will cover 10 square feet of a surface. A room has a total wall area of \\(w\\) square feet. Which equation represents the total amount of paint \\(P\\), in gallons, needed to paint the walls of the room twice?', '[\"\\\\(P = 20w\\\\)\",\"\\\\(P = 10w\\\\)\",\"\\\\(P = \\\\frac{w}{5}\\\\)\",\"\\\\(P = \\\\frac{w}{10}\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'math'),
(861, 19, 3, NULL, '[image] The table shows three values of \\(x\\) and their corresponding values of \\(y\\). There is a quadratic relationship between \\(x\\) and \\(y\\). An equation that represents this relationship can be written as \\(y = 24x^2 - bx - 128\\), where \\(b\\) is a constant. What is the value of \\(b\\)?', NULL, NULL, 1, 'https://i.postimg.cc/85pxm6jh/image.png', 'spr', '64', 'math'),
(862, 19, 4, NULL, 'The equation \\(E(t) = 5(1.2)^t\\) gives the estimated number of employees at a certain business, where \\(t\\) is the number of years since the business opened. Which of the following is the best interpretation of the number 5 in this context?', '[\"The increase in the estimated number of employees each year\",\"The estimated number of employees when the business opened\",\"The percent increase in the estimated number of employees each year\",\"The number of years the business has been open\"]', 1, 1, NULL, 'mcq', NULL, 'math'),
(863, 19, 5, NULL, 'Line \\(t\\) in the \\(xy\\)-plane has a slope of \\(\\frac{1}{7}\\) and passes through the point \\((35, -8)\\). Which equation defines line \\(t\\)?', '[\"\\\\(y = -13x + \\\\frac{1}{7}\\\\)\",\"\\\\(y = \\\\frac{x}{7} - 13\\\\)\",\"\\\\(y = \\\\frac{x}{7} - 8\\\\)\",\"\\\\(y = 35x - 8\\\\)\"]', 1, 1, NULL, 'mcq', NULL, 'math'),
(864, 19, 6, NULL, 'The area of a rectangular region is increasing at a rate of 210 square feet per hour. Which of the following is closest to this rate in square meters per minute? (Use 1 meter = 3.28 feet.)', '[\"0.33\",\"1.07\",\"11.48\",\"19.52\"]', 0, 1, NULL, 'mcq', NULL, 'math'),
(865, 19, 7, NULL, 'The scatterplot shows the relationship between \\(x\\) and \\(y\\) for the 9 data points in data set A. [image] A quadratic model for the data in data set A can be written as \\(y = 0.04x^2 - 0.07x + 6.59\\). The graph of this model is shown in the \\(xy\\)-plane. The data point at \\(x = 0\\) was found to be the result of a recording error and was removed from data set A to create data set B, consisting of the remaining 8 data points. A quadratic model for the data in data set B can be written as \\(y = ax^2 + bx + c\\), where \\(a\\), \\(b\\), and \\(c\\) are constants. If the quadratic models for data sets A and B are calculated in the same way, which of the following statements must be true? I. \\(a > 0.04\\) II. \\(c < 6.59\\)', '[\"I only\",\"II only\",\"I and II\",\"Neither I nor II\"]', 2, 1, 'https://i.postimg.cc/HL4fM2sm/image.png', 'mcq', NULL, 'math'),
(866, 19, 8, NULL, '\\(f(x) = (2x - 7)(2x + 5)\\) What is the minimum value of the given function?', '[\"-36\",\"\\\\(-\\\\frac{5}{2}\\\\)\",\"\\\\(\\\\frac{1}{2}\\\\)\",\"2\"]', 0, 1, NULL, 'mcq', NULL, 'math'),
(867, 19, 9, NULL, '\\(2x^2 + 18x + 2y^2 + 12y = \\frac{15}{2}\\) The given equation defines a circle in the \\(xy\\)-plane. What is the radius of the circle?', '[\"\\\\(\\\\frac{\\\\sqrt{30}}{2}\\\\)\",\"\\\\(\\\\sqrt{15}\\\\)\",\"\\\\(\\\\sqrt{33}\\\\)\",\"\\\\(\\\\frac{\\\\sqrt{498}}{2}\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'math'),
(868, 19, 10, NULL, '[image] Note: Figure not drawn to scale. A right triangle has the dimensions shown, in centimeters (cm). What is the area of this triangle, in \\(\\text{cm}^2\\)?', NULL, NULL, 1, 'https://i.postimg.cc/fyLnD9N6/image.png', 'spr', '12', 'math'),
(869, 19, 11, NULL, '[image] In the figure, line \\(AB\\) is parallel to line \\(CD\\), and line \\(AD\\) intersects line \\(BC\\) at point \\(E\\). If \\(y = 119\\) and \\(z = 113\\), what is the value of \\(x\\)?', '[\"52\",\"67\",\"128\",\"142\"]', 2, 1, 'https://i.postimg.cc/htVwFrmV/image.png', 'mcq', NULL, 'math'),
(870, 19, 12, NULL, 'A researcher investigated two species of mites: a predator and its prey. At the start of a week, there was an equal number of the two species. At the end of the week, the number of prey had increased by 1900% of the number of prey at the start of the week, and the number of predators had increased by 240% of the number of predators at the start of the week. The number of predators at the end of the week was \\(p\\%\\) less than the number of prey at the end of the week. What is the value of \\(p\\)?', NULL, NULL, 1, NULL, 'spr', '83', 'math'),
(871, 19, 13, NULL, 'Which expression is NOT a factor of \\(6,480x^4 - 1,280\\)?', '[\"\\\\(9x^2 + 4\\\\)\",\"\\\\(3x^2 - 2\\\\)\",\"\\\\(3x + 2\\\\)\",\"80\"]', 1, 1, NULL, 'mcq', NULL, 'math'),
(872, 19, 14, NULL, '\\(-4x + 24px = 72\\) In the given equation, \\(p\\) is a constant. The equation has no solution. What is the value of \\(p\\)?', '[\"0\",\"\\\\(\\\\frac{1}{6}\\\\)\",\"\\\\(\\\\frac{3}{4}\\\\)\",\"3\"]', 1, 1, NULL, 'mcq', NULL, 'math'),
(873, 19, 15, NULL, 'A zoologist observed the nests of wood ducks in an area. Each year, the zoologist recorded the number of eggs in each of the first 35 nests that were observed and created a frequency table for the data set. Which of the following frequency tables represents the data set with the smallest standard deviation?', '[\"https://i.postimg.cc/8cqy9JPn/image.png\",\"https://i.postimg.cc/502kCWRP/image.png\",\"https://i.postimg.cc/VLCZMRDp/image.png\",\"https://i.postimg.cc/cLG9cnzy/image.png\"]', 3, 1, NULL, 'mcq', NULL, 'math'),
(874, 19, 16, NULL, '\\((x + 2)(x - 12) = 0\\) What is the positive solution to the given equation?', NULL, NULL, 1, NULL, 'spr', '12', 'math'),
(875, 19, 17, NULL, 'The function \\(f\\) is a quadratic function. In the \\(xy\\)-plane, the graph of \\(y = f(x)\\) has a vertex at \\((1, 4)\\) and passes through the points \\((2, 28)\\) and \\((-1, 100)\\). What is the value of \\(f(-2) - f(0)\\)?', '[\"76\",\"124\",\"192\",\"220\"]', 2, 1, NULL, 'mcq', NULL, 'math'),
(876, 19, 18, NULL, '\\(2x^2 + 14x + 2y^2 + 20y = \\frac{15}{2}\\) The given equation defines a circle in the \\(xy\\)-plane. What is the radius of the circle?', '[\"\\\\(\\\\frac{\\\\sqrt{30}}{2}\\\\)\",\"\\\\(\\\\sqrt{15}\\\\)\",\"\\\\(\\\\sqrt{41}\\\\)\",\"\\\\(\\\\frac{\\\\sqrt{626}}{2}\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'math'),
(877, 19, 19, NULL, '\\(y = 6x^2 - 48x + 99\\) \\(y + 4 = 0\\) How many solutions are there to the given system of equations?', '[\"There is exactly 1 solution.\",\"There are exactly 2 solutions.\",\"There are exactly 3 solutions.\",\"There are no solutions.\"]', 3, 1, NULL, 'mcq', NULL, 'math'),
(878, 19, 20, NULL, '[image] The triangle in the figure above has side lengths 3, 4, and \\(2x\\). Which of the following is NOT a possible value of \\(x\\)?', '[\"1\",\"2.5\",\"3\",\"5\"]', 3, 1, 'https://i.postimg.cc/5yvGxqGW/image.png', 'mcq', NULL, 'math'),
(879, 19, 21, NULL, 'Line \\(p\\) in the \\(xy\\)-plane contains the points \\((6, 0)\\) and \\((6, 6)\\). Which equation defines line \\(p\\)?', '[\"\\\\(x = 0\\\\)\",\"\\\\(x = 6\\\\)\",\"\\\\(y = 0\\\\)\",\"\\\\(y = 6\\\\)\"]', 1, 1, NULL, 'mcq', NULL, 'math'),
(880, 19, 22, NULL, 'The function \\(f\\) is defined by \\(f(z) = 3z\\). Which of the following is equivalent to \\(f(z - 7)\\)?', '[\"\\\\(-3z\\\\)\",\"\\\\(3z - 7\\\\)\",\"\\\\(3z - 21\\\\)\",\"\\\\(-3z + 21\\\\)\"]', 2, 1, NULL, 'mcq', NULL, 'math'),
(881, 19, 1, NULL, 'The expression \\(\\frac{kx - 17}{2x^2 - 11x + 15}\\) is equivalent to \\(\\frac{p}{x - 3} - \\frac{1}{2x - 5}\\), where \\(k\\) and \\(p\\) are constants. What is the value of \\(p\\)?', '[\"\\\\(-16\\\\)\",\"\\\\(\\\\frac{14}{5}\\\\)\",\"\\\\(4\\\\)\",\"\\\\(7\\\\)\"]', 2, 2, NULL, 'mcq', NULL, 'math'),
(882, 19, 2, NULL, 'The measure of angle \\(F\\) is \\(\\frac{\\pi}{12}\\) radians. If the measure of angle \\(F\\) is \\(3n\\) degrees, where \\(n\\) is a constant, what is the value of \\(n\\)?', '[\"\\\\(3\\\\)\",\"\\\\(5\\\\)\",\"\\\\(12\\\\)\",\"\\\\(15\\\\)\"]', 3, 2, NULL, 'mcq', NULL, 'math'),
(883, 19, 3, NULL, 'The function \\(g\\) is defined by \\(g(x) = -2x(x + 4)(x - k)^2 + r\\), where \\(k\\) and \\(r\\) are integer constants. In the \\(xy\\)-plane, the graph of \\(y = g(x)\\) passes through the point \\((8, 17)\\), and \\(g(0) = 17\\). What is the value of \\(r + k\\)?', '[\"\\\\(-8\\\\)\",\"\\\\(0\\\\)\",\"\\\\(17\\\\)\",\"\\\\(25\\\\)\"]', 3, 2, NULL, 'mcq', NULL, 'math'),
(884, 19, 4, NULL, 'The function \\(f\\) is defined by \\(f(x) = 41(0.26)^x\\). For any positive integer \\(n\\), the value of \\(f(n)\\) is \\(p\\%\\) less than the value of \\(f(n - 1)\\). What is the value of \\(p\\)?', '[\"\\\\(74\\\\)\",\"\\\\(59\\\\)\",\"\\\\(41\\\\)\",\"\\\\(26\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'math'),
(885, 19, 5, NULL, '[image] The shaded region shown represents the solutions to which inequality?', '[\"\\\\(y \\\\ge -2x + 4\\\\)\",\"\\\\(y > 4x - 2\\\\)\",\"\\\\(y \\\\le -2x + 4\\\\)\",\"\\\\(y \\\\le 4x - 2\\\\)\"]', 0, 2, 'https://i.postimg.cc/MZjgbqGr/image.png', 'mcq', NULL, 'math'),
(886, 19, 6, NULL, '\\(f(x) = 21(1.20)^{\\frac{x}{3}}\\)\n\nFor the given function \\(f\\), the value of \\(f(x)\\) increases by \\(p\\%\\) for every increase of \\(x\\) by \\(6\\). What is the value of \\(p\\)?', NULL, NULL, 2, NULL, 'spr', '44', 'math'),
(887, 19, 7, NULL, 'A company developed a plan to set the selling price of a product. The company determined that for a selling price of \\(\\$90.00\\), zero products would be sold. For each \\(\\$1.50\\) decrease in the selling price, the number of products sold would increase by one. For a revenue of exactly \\(\\$1,336.50\\), which of the following could be the number of products sold? (\\(\\text{revenue} = \\text{price} \\times \\text{number of products sold}\\))', '[\"\\\\(27\\\\)\",\"\\\\(30\\\\)\",\"\\\\(831\\\\)\",\"\\\\(1,350\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'math'),
(888, 19, 8, NULL, '\\(y = 4x^2 - 24x + 38\\)\n\\(y + 3 = 0\\)\n\nHow many solutions are there to the given system of equations?', '[\"There is exactly 1 solution.\",\"There are exactly 2 solutions.\",\"There are exactly 3 solutions.\",\"There are no solutions.\"]', 3, 2, NULL, 'mcq', NULL, 'math'),
(889, 19, 9, NULL, '\\(-7x^2 + bx - 63 = 0\\)\n\nIn the given equation, \\(b\\) is a positive integer. The equation has no real solution. What is the largest possible value of \\(b\\)?', NULL, NULL, 2, NULL, 'spr', '41', 'math'),
(890, 19, 10, NULL, 'If \\(5 + \\frac{2(13 - x)}{7} = 3(13 - x) + 5\\), what is the value of \\(13 + x\\)?', NULL, NULL, 2, NULL, 'spr', '26', 'math'),
(891, 19, 11, NULL, 'The area of a rectangle is \\(60\\) square inches. The length of the longest side of the rectangle is \\(15\\) inches. What is the length, in inches, of the shortest side of this rectangle?', '[\"\\\\(4\\\\)\",\"\\\\(15\\\\)\",\"\\\\(30\\\\)\",\"\\\\(45\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'math'),
(892, 19, 12, NULL, 'For the linear function \\(g\\), \\(g(9) = 11\\) and \\(g(x + 1) - g(x) = 2\\). Which equation defines \\(g\\)?', '[\"\\\\(g(x) = 9x + 2\\\\)\",\"\\\\(g(x) = 9x + 11\\\\)\",\"\\\\(g(x) = 2x - 18\\\\)\",\"\\\\(g(x) = 2x - 7\\\\)\"]', 3, 2, NULL, 'mcq', NULL, 'math'),
(893, 19, 13, NULL, '[image] For the linear function \\(f\\), the table shows three values of \\(x\\) and their corresponding values of \\(f(x)\\). Function \\(f\\) is defined by \\(f(x) = rx + s\\), where \\(r\\) and \\(s\\) are constants. What is the value of \\(rs\\)?', NULL, NULL, 2, 'https://i.postimg.cc/c1Y5thDR/image.png', 'spr', '507', 'math'),
(894, 19, 14, NULL, '\\(57x^{18} + bx^9 + 34\\)\n\nThe given expression, where \\(b\\) is a constant, is equivalent to \\((3x^9 + q)(rx^9 + 2)\\), where \\(q\\) and \\(r\\) are constants. What is the value of \\(b\\)?', NULL, NULL, 2, NULL, 'spr', '36', 'math'),
(895, 19, 15, NULL, '\\(g(x) = x^3 + ax^2 + bx + c\\)\n\nThe function \\(g\\) is defined by the given equation, where \\(a\\), \\(b\\), and \\(c\\) are integer constants. The zeros of the function are \\(-2\\), \\(-7\\), and \\(3\\). What is the value of \\(a\\)?', '[\"\\\\(-42\\\\)\",\"\\\\(-6\\\\)\",\"\\\\(6\\\\)\",\"\\\\(42\\\\)\"]', 2, 2, NULL, 'mcq', NULL, 'math'),
(896, 19, 16, NULL, 'A circle in the \\(xy\\)-plane has its center at \\((-4, 4)\\) and has a radius of \\(6\\). An equation of this circle is \\(x^2 + y^2 + ax + by + c = 0\\), where \\(a\\), \\(b\\), and \\(c\\) are constants. What is the value of \\(c\\)?', NULL, NULL, 2, NULL, 'spr', '-4', 'math'),
(897, 19, 17, NULL, 'A model estimates that the population of a state was \\(4\\) million in 1980 and increased by \\(0.041\\) million each year until 2007. According to the model, what was the estimated population of this state, in millions, \\(10\\) years after 1980?', NULL, NULL, 2, NULL, 'spr', '4.41', 'math'),
(898, 19, 18, NULL, 'In triangle \\(RST\\), angle \\(T\\) is a right angle, point \\(L\\) lies on \\(\\overline{RS}\\), point \\(K\\) lies on \\(\\overline{ST}\\), and \\(\\overline{LK}\\) is parallel to \\(\\overline{RT}\\). If the length of \\(\\overline{RT}\\) is \\(63\\) units, the length of \\(\\overline{LK}\\) is \\(21\\) units, and the area of triangle \\(RST\\) is \\(252\\) square units, what is the length of \\(\\overline{KT}\\), in units?', NULL, NULL, 2, NULL, 'spr', '112/21', 'math'),
(899, 19, 19, NULL, 'A car dealership has only sedans, SUVs, and minivans for sale. On Monday, \\(20\\%\\) of the vehicles for sale were sedans and \\(50\\%\\) were SUVs. If there were \\(62\\) sedans for sale at the dealership on Monday, how many minivans were for sale?', '[\"\\\\(93\\\\)\",\"\\\\(310\\\\)\",\"\\\\(9\\\\)\",\"\\\\(36\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'math'),
(900, 19, 20, NULL, 'An exponential function \\(f\\) gives the estimated amount of an X-ray beam\'s initial intensity remaining after passing through a \\(w\\)-centimeter-thick window made of beryllium. The function estimates that after passing through a \\(1.8\\)-centimeter-thick window, the amount of the X-ray beam\'s initial intensity remaining is \\(0.65\\). Which equation could define \\(f\\)?', '[\"\\\\(f(w) = 0.65(0.79)^{w - 1.8}\\\\)\",\"\\\\(f(w) = 0.65(0.79)^{\\\\frac{w}{1.8}}\\\\)\",\"\\\\(f(w) = 0.65(1.8)^w\\\\)\",\"\\\\(f(w) = 1.8(0.65)^w\\\\)\"]', 0, 2, NULL, 'mcq', NULL, 'math'),
(901, 19, 21, NULL, '[image] In the figure, \\(\\overline{BC}\\) is parallel to \\(\\overline{DE}\\). If the length of \\(\\overline{DE}\\) is \\(162\\) and the length of \\(\\overline{AE}\\) is \\(270\\), what is the value of \\(\\tan x^\\circ\\)?', '[\"\\\\(\\\\frac{270}{162}\\\\)\",\"\\\\(\\\\frac{216}{162}\\\\)\",\"\\\\(\\\\frac{162}{270}\\\\)\",\"\\\\(\\\\frac{162}{216}\\\\)\"]', 1, 2, 'https://i.postimg.cc/CxvvpQ1Y/image.png', 'mcq', NULL, 'math'),
(902, 19, 22, NULL, 'The function \\(f\\) is defined by \\(f(x) = |x - 6x|\\). What value of \\(a\\) satisfies \\(f(1) - f(a) = -15\\)?', '[\"\\\\(-16\\\\)\",\"\\\\(3\\\\)\",\"\\\\(4\\\\)\",\"\\\\(75\\\\)\"]', 2, 2, NULL, 'mcq', NULL, 'math');
